-- V1.0.58：基础词书重建（中考+高考全集 3698 词）+ 词库补录 1284 词
-- 目标库：exercise_db
-- 风险：中（纯 DML；不建表、不删列。改动三处：词书编码、词书词条、词库补录）
-- 说明：
--   1. basic_500 的定位一直是「入门起步」，但内容取的是四级词频前 500，
--      里面混有 82 个既非中考也非高考的词（program/economic/congress…），
--      末尾是 investigation/nuclear/researcher/conflict —— 是高频，不是基础。
--   2. 本次改用 ECDICT 的中考词汇(book 9, 1592) + 高考词汇(book 4, 3655) 合并去重，
--      中考优先、高考补充，共 3698 词，全部为高中阶段基础词。
--   3. 词书编码 basic_500 → basic_foundation（原编码名里的 500 已与内容量不符）。
--      word_book.code 是 UNIQUE 键、word_book_item.book_code 无外键，改码顺序安全。
--   4. 词书显示名「四级精选」按既定决策保持不变，只补充 description 说明真实内容。
--   5. 词书 level 保持 CET4：背单词取题按词书等级找 CET4 题，
--      基础词中有 1284 个不在四级考纲内、无 CET4 题，按既有规则降级为 CARD 词卡。
--   6. 词库补录 1284 个缺失词：中文释义取 ECDICT translation JSON，
--      音标取英式（缺则取美式），词性从 meanings JSON 推导（ECDICT 的 pos 列全为 NULL），
--      例句取 word_example 表首条。
--
-- 回滚：
--   DELETE FROM `word_book_item` WHERE `book_code` = 'basic_foundation';
--   UPDATE `word_book` SET `code`='basic_500', `description`='四级考纲内最常用的词，适合起步'
--     WHERE `code` = 'basic_foundation';
--   UPDATE `user_word_learn_log` SET `book_code`='basic_500' WHERE `book_code`='basic_foundation';
--   DELETE FROM `word_dictionary` WHERE `word` IN (/* 1284 个补录词，见 sql/backup 备份 */);
--   原 basic_500 的 500 条词条见 exercise_db 全量备份，可用其 word_book_item 段还原。

-- ---------- 1. 词库补录：基础词中本库缺失的 1284 个 ----------
