  ('but', '/bʌt/', 'prep. 除了 conj. 但是 adv. 仅仅', 'prep', 'I may be antisocial, but it doesn''t mean I don''t talk to people.', '我或许不善于社交,但这并不意味我不和别人交谈。', 'CET4'),
