  ('his', '/hiz/', 'pron. 他的 [化] 组氨酸', 'pron', 'With the heirless king going crazy and royal family poisoned, the general of the army finally had his chance to usurp the throne.', '随着无继承人的国王的发疯和王室家族的中毒，将军终于有机会篡夺王位。', 'CET4'),
