  ('who', '/hu:/', 'pron. 谁', 'pron', 'I don''t like it when mathematicians who know much more than I do can''t express themselves explicitly.', '我不喜欢那些数学家知道的比我多得多，却不知道清楚地表达自己。', 'CET4'),
  ('get', '/get/', 'vt. 得到, 获得, 变成, 使得, 收获, 接通, 抓住, 染上 vi. 到达, 成为, 变得 n. (网球等)救球, 生殖, 幼兽 [计] 取得指令, 获取文件', 'vt', 'The police will get you to find the bullets.', '警察会让你去找子弹的。', 'CET4'),
