  ('more', '/mɒ:/', 'n. 更多 a. 多的, 程度较大的, 更大的 adv. 多, 更多, 进一步 [计] DOS外部命令:显示满屏后自动暂停, 并显示:"--More--", 按任意键继续', 'n', 'I always liked mysterious characters more.', '我一直都比较喜欢神秘一点的人物。', 'CET4'),
