  ('want', '/wɒnt/', 'n. 需要的东西, 缺乏, 贫困, 需要 vt. 要, 希望, 应该, 缺少 vi. 生活困苦, 需要, 缺少', 'n', 'When I grow up, I want to be a king.', '我长大后想当国王。', 'CET4'),
  ('way', '/wei/', 'n. 路, 路线, 路途, 方法, 道路, 情形, 规模, 习惯, 行业, 方面 adv. 远远地, 非常', 'n', 'You are in my way.', '你挡住了我的路。', 'CET4'),
  ('look', '/luk/', 'n. 一看, 神色, 样子, 面容 vi. 看, 注意, 朝着, 显得 vt. 打量, 看上去与...一样, 以眼色(或脸色)显示, 期待', 'n', 'I wouldn''t have thought I would someday look up "Viagra" in Wikipedia.', '我不会想到有一天我会在维基百科查找“伟哥”。', 'CET4'),
