  ('world', '/wә:ld/', 'n. 世界, 地球, 宇宙, 万物, 世人, 人间, 领域, 世事, 世故, 社会生活, 大量 [法] 世界, 地球, 世人', 'n', 'Education in this world disappoints me.', '世界上的教育都让我失望。', 'CET4'),
