  ('turn', '/tә:n/', 'n. 转弯, 转动, 旋转, 翻转, 一圈, 顺次, 改动, 变化, 性格, 特色, 形状, 转折 vt. 使旋转, 转弯, 转动, 使转向, 驱赶, 阻挡, 兑换, 改写, 使作对, 绕过, 使流通 vi. 转动, 转弯, 转向, 翻转, 回转, 改变, 转身, 变成, 变质, 晕眩, 易脱手', 'n', 'Mathematicians are like French people: whatever you tell them they translate it into their own language and turn it into something totally different.', '数学家就像是法国人：不管你跟他们说什么，他们都会把这翻译成他们自己的语言，并将其变成一些完全不同的东西。', 'CET4'),
  ('problem', '/''prɒblәm/', 'n. 问题, 难题 a. 成问题的, 难处理的', 'n', 'Then there is a problem...', '那就表示有问题...', 'CET4'),
  ('every', '/''evri/', 'a. 每一, 所有的', 'adj', 'Back in high school, I got up at 6 a.m. every morning.', '以前读高中的时候﹐我每天早上六点起床。', 'CET4'),
  ('start', '/stɑ:t/', 'n. 惊起, 出发, 开端, 起点, 吃惊, 有利条件 vi. 开始, 出发, 启动, 跳起, 吃惊, 出现, 松动, 脱落, 起价, 参赛 vt. 使惊起, 开动, 发动, 启动, 开始, 创办, 提议, 使松动, 使脱落, 起用 [计] 起始', 'n', 'You''d better start now.', '你最好现在就开始。', 'CET4'),
  ('hand', '/hænd/', 'n. 手, 爪, 指针, 掌握, 协助, 人手, 手艺, 手迹, 支配, 插手 vt. 交给, 支持, 搀扶', 'n', 'At the age of six he had learned to use the typewriter and told the teacher that he did not need to learn to write by hand.', '他六岁的时候学会了用打字机，便和老师说他不用学执笔写字了。', 'CET4'),
  ('american', '/ә''merikәn/', 'n. 美国人 a. 美国的, 美洲的', 'n', NULL, NULL, 'CET4'),
  ('show', '/ʃәu/', 'n. 显示, 表现, 展览, 卖弄, 炫耀, 外观, 演出, 洋相 vt. 表示, 显示, 展现, 陈列, 演出, 表明, 指出, 带领 vi. 露面, 显现, 演出 [计] 显示', 'n', 'I was wondering if you were going to show up today.', '我在想你今天会不会来。', 'CET4'),
  ('place', '/pleis/', 'n. 地方, 地点, 位置, 住所, 座位, 地位, 处境, 特权, 空间, 余地, 职务, 位 vt. 放置, 寄予, 认出, 评定, 任命 vi. 名次列前', 'n', 'Place the deck of cards on the oaken table.', '把扑克牌放在橡木桌上。', 'CET4'),
  ('such', '/sʌtʃ/', 'a. 如此的, 这样的', 'adj', 'When the body is touched, receptors in the skin send messages to the brain causing the release of chemicals such as endorphins.', '当身体受到外界触碰的时候，皮肤的感受器就会向大脑发出信息，令大脑释放安多芬等的化学物质。', 'CET4'),
  ('again', '/ә''gein/', 'adv. 再一次, 又, 到原处', 'adv', 'Could you call again later, please?', '你可以晚点再打电话来吗？', 'CET4'),
  ('few', '/fju:/', 'a. 很少的, 不多的, 少数的 n. 少数', 'adj', 'If I wanted to scare you, I would tell you what I dreamt about a few weeks ago.', '如果我是想吓你，我就会告诉你我几周前梦到的事。', 'CET4'),
  ('week', '/wi:k/', 'n. 星期, 周', 'n', 'It may freeze next week.', '下周可能会结冰。', 'CET4'),
  ('company', '/''kʌmpәni/', 'n. 公司, 友伴, 交往, 连队, 朋友, 一群 vt. 陪伴 vi. 交往', 'n', 'If you don''t want to stay alone, I can keep you company.', '如果你不想一个人呆着，我可以陪着你。', 'CET4'),
  ('each', '/i:tʃ/', 'a. 每个, 每一 adv. 每个 pron. 每个, 个人, 各自', 'adj', 'Each person is a world.', '每个人都是一个世界。', 'CET4'),
  ('right', '/rait/', 'n. 权利, 右边, 正义, 右派, 公正 a. 正确的, 对的, 恰当的, 正常的, 正直的, 正面的, 右方的 adv. 正确地, 以有利结果, 一直, 直接, 向右 vt. 扶直, 整理, 纠正, 伸冤, 使昭雪 vi. 恢复平衡 [计] 右, 权利', 'n', 'Perhaps you are right, I have been selfish.', '也许你说得对。我一直都很自私。', 'CET4'),
  ('hear', '/hiә/', 'vt. 听到, 倾听, 听说, 审理 vi. 听见, 听', 'vt', 'Most people only want to hear their own truth.', '大部分人只想听到他们自己的真理。', 'CET4'),
  ('question', '/''kwestʃәn/', 'n. 问题, 询问 v. 询问, 审问, 怀疑 [计] 询问', 'n', 'I need to ask you a silly question.', '我必须问你一个蠢问题。', 'CET4'),
  ('during', '/''djuәriŋ/', 'prep. 在...的时候', 'prep', 'I slept a little during lunch break because I was so tired.', '我在午休时间睡了一会儿，因为我太累了。', 'CET4'),
  ('play', '/plei/', 'n. 游戏, 游玩, 玩笑, 运动, 比赛, 赌博, 跳动, 表演, 剧本 v. 玩, 游戏, 假装, 开玩笑, 比赛, 扮演, 演奏, 演戏, 传摇曳, (使)跳动 [计] 播放', 'n', 'I will play Sudoku then instead of continuing to bother you.', '那我就不继续打扰你，玩数独游戏去了。', 'CET4'),
  ('run', '/rʌn/', 'n. 跑, 赛跑, 奔跑, 奔跑的路程, 趋向, 流出, 运转时间, 连续 vi. 跑, 奔跑, 跑步, 赛跑, 竞赛, 行驶, 运转, 进行, 蔓延 vt. 使跑, 参赛, 追究, 驾驶, 开动, 管理, 经营, 使流出, 运行 a. 熔化的, 融化的, 浇铸的 run的过去式和过去分词 [计] 运行', 'n', 'Someday I''ll run like the wind.', '有一天，我会跑得像风一样快。', 'CET4'),
  ('small', '/smɒ:l/', 'a. 小的, 少的, 小型的, 低微的, 小气的, 细微的 adv. 些微地 n. 狭小部分', 'adj', 'When we are small, everything seems so big.', '我们小时候，所有的一切对我们来说都显得那么大。。。', 'CET4'),
  ('number', '/''nʌmbә/', 'n. 数, 数字, 数目, 号码 vt. 数, 计算, 共计 vi. 计算, 报数 [计] 数字', 'n', 'I forget your phone number.', '我忘了你的电话号码。', 'CET4'),
  ('off', '/ɒf/', 'a. 关着的, 不再生效的, 处于...境况的, 休假的, 空闲的 adv. 走开, ...掉, ...下, 休息, 出发, 隔断 prep. 离开, 脱落, 不在从事......, 在...之外 vi. 离开, 滚开 vt. 杀死 n. 关闭状态 [计] 关闭, 清屏命令', 'adj', 'I shouldn''t have logged off.', '我不该退出的。', 'CET4'),
  ('always', '/''ɒ:lweiz/', 'adv. 总是, 始终', 'adv', 'I always liked mysterious characters more.', '我一直都比较喜欢神秘一点的人物。', 'CET4'),
  ('move', '/mu:v/', 'n. 移动, 迁居, 步骤 vt. 移动, 开动, 感动, 搬(家) vi. 移动, 离开, 运行, 迁移, 摇动, 搬家, 交往, 进展, 脱手 [计] 移动; 传送; DOS外部命令:移动文件, 它可将文件移动到指定的地方', 'n', 'It''s your move.', '该你走了。', 'CET4'),
  ('night', '/nait/', 'n. 夜, 夜晚, 晚上, 黑暗, 夜晚的工作 [法] 夜, 黑夜, 黑暗', 'n', 'For some reason I feel more alive at night.', '不知道为什么我夜里觉得比较有活力。', 'CET4'),
  ('live', '/liv.laiv/', 'a. 活的, 生动的, 精力充沛的, 实况转播的 vi. 活, 生存, 居住 vt. 过着, 度过, 经历 adv. 实况地', 'adj', 'I can''t live that kind of life.', '我不能这样活着。', 'CET4'),
  ('believe', '/bi''li:v/', 'v. 相信', 'v', 'It''s no use pretending to make me believe that I believe things you don''t believe!', '要我相信我会相信你不相信的东西是没用的！', 'CET4'),
  ('hold', '/hәuld/', 'n. 把握, 把持力, 柄, 控制, 掌握, 监禁 vt. 保存, 握住, 拿住, 占据, 持有, 拥有 vi. 支持, 持续, 有效 n. 保留 [计] 保留', 'n', 'Hold on, someone is knocking at my door.', '等等，有人在敲我的门。', 'CET4'),
  ('today', '/tә''dei/', 'n. 今天, 当今, 现在 adv. 今天, 当今', 'n', 'I was wondering if you were going to show up today.', '我在想你今天会不会来。', 'CET4'),
  ('bring', '/briŋ/', 'vt. 带来, 产生, 促使, 提出 vi. 生产', 'vt', 'I''ll bring you the bill immediately.', '我马上把帐单拿给您。', 'CET4'),
  ('next', '/''nekst/', 'n. 下一个 a. 下一个的, 其次的, 贴近的 adv. 然后, 下次, 次于 [计] 近邻干扰', 'n', 'It may freeze next week.', '下周可能会结冰。', 'CET4'),
  ('without', '/wi''ðaut/', 'prep. 没有, 不, 在...之外 adv. 在外面, 户外 n. 外面, 外部', 'prep', 'I learned to live without her.', '我学会了不靠她生活。', 'CET4'),
  ('before', '/bi''fɒ:/', 'prep. 在...之前 conj. 在...之前 adv. 在前', 'prep', 'There will always be things I will never learn, I don''t have eternity before me!', '总有一些东西我永远不能学会，我的生命不是永恒的！', 'CET4'),
  ('large', '/lɑ:dʒ/', 'a. 大的, 大量的, 宽大的, 广博的 adv. 大大地, 夸大地', 'adj', 'Kyoto is not as large as Osaka.', '京都不如大阪大。', 'CET4'),
  ('must', '/mʌst/', 'n. 必须, 未发酵葡萄汁, 绝对必要的事物 aux. 必须', 'n', 'We must learn to live together as brothers, or we will perish together as fools.', '我们必须学会像兄弟一样共同生活，要么就像傻子一样同归于尽。', 'CET4'),
  ('home', '/hәum/', 'n. 家, 避难所, 故乡 a. 家庭的, 国内的, 打中目标的 adv. 在家, 在本国, 打中目标地 [计] 返回始位', 'n', 'Why don''t we go home?', '我们何不回家呢？', 'CET4'),
  ('under', '/''ʌndә/', 'prep. 在...之下, 低于 a. 下面的, 从属的 adv. 在下面', 'prep', 'Are you feeling under the weather?', '你感觉不舒服吗？', 'CET4'),
  ('water', '/''wɒ:tә/', 'n. 水, 雨水, 海水, 水位, 水面, 流水 vt. 给...浇水, 供以水, 注入水, 使湿 vi. 流泪, 流口水, 加水 a. 水的, 水上的, 水生的, 含水的', 'n', 'Both air and water are indispensable for life.', '没有空气和水，人类就无法生存。', 'CET4'),
  ('room', '/ru:m/', 'n. 房间, 空位, 场所 vi. 住宿, 居住 vt. 留宿', 'n', 'If you don''t have anything to do, look at the ceiling of your room.', '如果你没事做，那就看你房间的天花板。', 'CET4'),
  ('write', '/rait/', 'vt. 书写, 著述, 写, 写满, 写信给 vi. 写, 写字, 写信, 写作, 作曲 [计] 书写器', 'vt', 'Most people write about their daily life.', '大部分人写的东西是关于他们的日常生活的。', 'CET4'),
  ('mother', '/''mʌðә/', 'n. 母亲, 修女院长 vt. 产生, 照看, 收养', 'n', 'Who is it? "It''s your mother."', '“是谁？”“是你妈妈。”', 'CET4'),
  ('money', '/''mʌni/', 'n. 金钱, 一笔款, 财富, 货币, 金额 [经] 货币, 金钱, 财产', 'n', 'Hey, I may have no money, but I still have my pride.', '嗨，我可能没钱，但我一直有我的骄傲。', 'CET4'),
  ('story', '/''stɒ:ri/', 'n. 故事, 小说, 传奇, 描述, 阅历, 经历, 层', 'n', 'If anyone was to ask what the point of the story is, I really don''t know.', '如果有人问起这个故事的用意是什么，我还真不知道。', 'CET4'),
  ('young', '/jʌŋ/', 'a. 年轻的, 无经验的, 朝气蓬勃的 n. 青年们, 幼小动物, 崽', 'adj', 'The proliferation of Internet usage has given birth to a new generation of young people.', '互联网的广泛应用使新一代的年轻人诞生了。', 'CET4'),
  ('month', '/mʌnθ/', 'n. 月 [经] 月', 'n', 'Each member has to pay 10,000 yen a month.', '每位会员每月需支付一万日元。', 'CET4');;

INSERT INTO `word_dictionary` (`word`, `phonetic`, `translation`, `pos`, `example`, `example_translation`, `level`) VALUES
  ('different', '/''difәrәnt/', 'a. 不同的 [机] 差动, 微分的, 差速器', 'adj', 'I suppose it''s different when you think about it over the long term.', '我认为你考虑久了就会不一样了。', 'CET4'),
  ('lot', '/lɒt/', 'n. 运气, 签, 抽签, 份额, 许多, 一堆 vt. 划分 vi. 抽签, 抓阄', 'n', 'There are a lot of things you don''t know about my personality.', '你对我的个性还不太清楚。', 'CET4'),
  ('study', '/''stʌdi/', 'n. 学习, 研究, 学科, 论文, 求学, 书房, 试作 vt. 学习, 读书, 研究, 考虑, 计划 vi. 学习, 思索', 'n', 'Tomorrow, I''m going to study at the library.', '我明天去图书馆温习。', 'CET4'),
  ('book', '/buk/', 'n. 书, 书籍, 帐簿, 名册, 工作簿 v. 登记, 预订 [计] 工作簿', 'n', 'Take a book and read it.', '拿本书读！', 'CET4'),
  ('eye', '/ai/', 'n. 眼睛, 视力, 看 vt. 看, 注视', 'n', 'The headline caught my eye this morning.', '大标题今天早上吸引了我的注意。', 'CET4'),
  ('job', '/dʒɒb/', 'n. 工作, 零活, 职业, 事情 vi. 做零工, 打杂, 做股票经纪, 假公济私 vt. 代客买卖, 批发, 承包, 欺骗 [计] 作业', 'n', 'I like my job very much.', '我非常喜欢我的工作。', 'CET4'),
  ('word', '/wә:d/', 'n. 话, 消息, 词, 诺言, 命令 vt. 用言辞表达 [计] 字', 'n', 'I give you my word.', '我向你保证。', 'CET4'),
  ('though', '/ðәu/', 'adv. 然而, 可是 conj. 虽然, 纵然', 'adv', 'I don''t want to lose my ideas, even though some of them are a bit extreme.', '我不想放弃我的想法，虽然一些想法有点极端。', 'CET4'),
  ('four', '/fɒ:/', 'num. 四, 四个 [机] 四冲程循环', 'num', 'I am four months pregnant.', '我怀孕四个月了。', 'CET4'),
  ('london', '/''lʌndәn/', 'n. 伦敦', 'n', NULL, NULL, 'CET4'),
  ('side', '/said/', 'n. 旁边, 侧, 方面, 胁, 侧边, 血统 a. 旁的, 侧的, 次要的 vt. 同意, 支持 vi. 支持, 赞助', 'n', 'You''re by my side; everything''s fine now.', '你在我旁边，现在一切都好了。', 'CET4'),
  ('kind', '/kaind/', 'n. 种类, 性质, 方式 a. 亲切的, 仁慈的, 和蔼的', 'n', 'I can''t live that kind of life.', '我不能这样活着。', 'CET4'),
  ('head', '/hed/', 'n. 头, 头脑, 领袖, 脑袋, 最前的部分 vt. 为首, 朝向, 前进, 用头顶 vi. 朝特定方向行进, (作物)结穗 a. 头的, 在顶端的, 主要的 [计] 磁头; 冲头', 'n', 'Our new head office is in Tokyo.', '我们的新总部位于东京。', 'CET4'),
  ('far', '/fɑ:/', 'a. 远的, 久远的, 遥远的 adv. 甚远地, 很, 到很深的程度, 到很远的距离', 'adj', 'I want a boat that will take me far away from here.', '我想要一艘船带我远离这里。', 'CET4'),
  ('black', '/blæk/', 'n. 黑色, 黑颜料 a. 黑色的', 'n', 'She was wearing a black hat.', '她戴着黑帽子。', 'CET4'),
  ('long', '/lɒŋ/', 'a. 长的, 长久的, 冗长的, 做多头的 vi. 渴望, 热望, 极想 adv. 长久, 始终 n. 长时间, 长信号, 长整型 [计] 长, 长整型', 'adj', 'I suppose it''s different when you think about it over the long term.', '我认为你考虑久了就会不一样了。', 'CET4'),
  ('both', '/bәuθ/', 'a. 两者的 adv. 两者都 pron. 两者', 'adj', 'When both girls told John they had feelings for him, he was in a quandary as to which girl he should be with.', '当两个女生都跟约翰宣称她们对他有感觉时，他不知道该跟哪个谈恋爱了。', 'CET4'),
  ('little', '/''litl/', 'n. 一点点, 少许, 一会儿, 短时间 a. 小的, 很少的, 幼小的, 琐碎的, 短暂的, 矮小的 adv. 很少, 稍微, 完全不', 'n', 'Poor is not the one who has too little, but the one who wants too much.', '贫穷的不是拥有太少的人，而是想要太多的人。', 'CET4'),
  ('house', '/haus/', 'n. 房子, 住宅, 机构, 议院, 家族, 家庭 vt. 给...房子住, 收藏 vi. 住, 躲藏', 'n', 'I wish I could live near your house.', '我希望住在你家附近。', 'CET4'),
  ('yes', '/jes/', 'adv. 是 n. 是, 同意 v. 同意', 'adv', 'It is difficult to keep up a conversation with someone who only says "yes" and "no".', '和一个只说"是"与"否"的人维持一段对话是很难的。', 'CET4'),
  ('since', '/sins/', 'prep. 自...以后, 自...以来 adv. 自那时以后 conj. 既然, 自...以后, 自...以来', 'prep', 'Since Mario lied to me, I don''t speak to him anymore.', '自从马里奥对我撒了谎，我就再也不跟他说话了。', 'CET4'),
  ('service', '/''sә:vis/', 'n. 服务, 贡献, 雇佣, 公职, 服役, 功劳, 仪式, 送达, 行政部门 vt. 保养, 维修 a. 武装部队的, 服务性的, 仆人的, 耐用的 [计] 服务, 业务', 'n', 'Is there a service charge for that?', '要收服务费吗?', 'CET4'),
  ('around', '/ә''raund/', 'prep. 包围, 在...周围, 四处 adv. 兜着圈子, 在附近, 到处', 'prep', 'With so many people around he naturally became a bit nervous.', '他被很多人围着，自然变得有点紧张。', 'CET4'),
  ('friend', '/frend/', 'n. 朋友, 支持者, 赞助者 [法] 朋友, 友人, 赞助者', 'n', 'This is my friend Rachel. We went to high school together.', '这是我朋友Rachel，我们当时在同一所高中。', 'CET4'),
  ('important', '/im''pɒ:tәnt/', 'a. 重要的, 有地位的, 大量的, 显要的, 自负的 [计] 要点', 'adj', 'This is not important.', '这个不重要。', 'CET4'),
  ('father', '/''fɑ:ðә/', 'n. 父亲, 祖先, 长辈, 神父, 创始者 vt. 当...的父亲, 保护, 创作, 发明, 培养', 'n', 'Like father, like son.', '有其父必有其子。', 'CET4'),
  ('sit', '/sit/', 'vi. 坐, 就座, 坐落 vt. 使就座, 骑 n. 坐, 衣服合身', 'vi', 'I''m going to sit on the bench over there next to the street lamp.', '我会在那盏街灯旁边的长凳上坐下来。', 'CET4'),
  ('away', '/ә''wei/', 'adv. 离去', 'adv', 'You''re just running away from life''s problems.', '你只会逃避生活问题。', 'CET4'),
