  ('name', '/neim/', 'n. 名字, 名称, 姓名, 名义, 名誉, 文件名 vt. 命名, 称呼, 任命, 提名, 列举 a. 姓名的, 据以取名的 [计] 名称, 文件名, 姓名', 'n', 'My name is Jack.', '我叫Jack。', 'CET4'),
