  ('learn', '/lә:n/', 'vt. 学习；认识到；得知', 'vt', 'I thought you liked to learn new things.', '我以为你喜欢学习新事物。', 'CET4'),
  ('change', '/tʃeindʒ/', 'n. 变化, 找回的零钱, 找头, 更换 vt. 改变, 更换, 兑换', 'n', 'Here is your change.', '这是你零钱。', 'CET4'),
  ('minute', '/''minit. mai''nju:t/', 'n. 分, 分钟, 片刻, 备忘录, 笔记 vt. 记录, 摘录, 测定时间 a. 微小的, 详细的', 'n', 'The statue of the Minute Man commemorates the valiant soldiers who fought in the Revolutionary War.', '民兵雕像是为了纪念独立战争中英勇作战的士兵。', 'CET4'),
