  ('idea', '/ai''diә/', 'n. 主意, 办法, 理想, 思想, 概念, 意见 [医] 观念, 思想', 'n', 'The last person I told my idea to thought I was nuts.', '最后一个听我说我的主意的人认为我疯了。', 'CET4'),
  ('body', '/''bɒdi/', 'n. 身体, 人, 尸体, 主要部分, 团体 vt. 赋以形体 [计] 体', 'n', 'When the body is touched, receptors in the skin send messages to the brain causing the release of chemicals such as endorphins.', '当身体受到外界触碰的时候，皮肤的感受器就会向大脑发出信息，令大脑释放安多芬等的化学物质。', 'CET4'),
  ('information', '/.infә''meiʃәn/', 'n. 消息, 知识, 通知, 情报, 信息, 问讯处, 起诉 [计] 信息', 'n', 'The information you gave me is of little use.', '你给我的资料没有多大的用处。', 'CET4'),
  ('nothing', '/''nʌθiŋ/', 'n. 无, 不关紧要之事, 零 adv. 毫不, 决不 interj. 什么也没有, 无', 'n', 'I have nothing better to do.', '我没有其他更好的事情去做。', 'CET4'),
  ('ago', '/ә''gәu/', 'adv. 以前', 'adv', 'If I wanted to scare you, I would tell you what I dreamt about a few weeks ago.', '如果我是想吓你，我就会告诉你我几周前梦到的事。', 'CET4'),
