  ('whether', '/''hweðә/', 'conj. 是否, 不论 pron. 两个中的哪一个', 'conj', 'It is up to you to decide whether we will go there or not.', '该由你来决定我们去不去那儿。', 'CET4'),
  ('watch', '/wɒtʃ/', 'n. 观察, 手表, 看守, 守护, 监视, 值班人 vt. 看, 注视, 照顾, 看守, 守护, 监视 vi. 观看, 注视, 守侯', 'n', 'Did you watch the game?', '你看了比赛吗？', 'CET4'),
