  ('spend', '/spend/', 'vt. 花费, 浪费, 度过, 消耗, 消磨 vi. 花费, 用尽', 'vt', 'Prime numbers are like life; they are completely logical, but impossible to find the rules for, even if you spend all your time thinking about it.', '质数就像人生，它们完全是合逻辑的，但就算你花多少时间来思考，也不能找到它们背后的规律。', 'CET4'),
