  ('low', '/lәu/', 'n. 低点, 低价, 低, 牛叫声 a. 低的, 消沉的, 低等的, 浅的, 卑贱的 adv. 低下地, 谦卑地, 低 vi. 牛叫', 'n', 'His low salary prevents him from buying the house.', '因为他的薪水太低，他买不起那栋房子。', 'CET4'),
