  ('remember', '/ri''membә/', 'vt. 记得, 回忆起, 记住, 铭记, 纪念 vi. 记得', 'vt', 'I find words with concise definitions to be the easiest to remember.', '我发现有明确定义的词最容易记住。', 'CET4'),
  ('foot', '/fut/', 'n. 脚, 步调, 英尺, 底部, 末尾, 步兵 vt. 走在...上, 给...换底, 支付 vi. 跳舞, 步行, 总计', 'n', 'Tom goes to school on foot.', '汤姆走路去上学。', 'CET4'),
