  ('maybe', '/''meibi:/', 'adv. 也许, 大概 n. 可能性', 'adv', 'Maybe he will be a good teacher.', '也许他会是一个很好的老师。', 'CET4'),
  ('able', '/''eibl/', 'a. 能干的, 能够的', 'adj', 'Any universe simple enough to be understood is too simple to produce a mind able to understand it.', '任何简单到可以被了解的宇宙便太过简单而无法产生可以了解它的心灵。', 'CET4'),
  ('age', '/eidʒ/', 'n. 年龄, 老年, 成年, 寿命, 时代, 时期 v. 变老, 成熟', 'n', 'At the age of six he had learned to use the typewriter and told the teacher that he did not need to learn to write by hand.', '他六岁的时候学会了用打字机，便和老师说他不用学执笔写字了。', 'CET4'),
  ('everything', '/''evriθiŋ/', 'pron. 每件事物, 所有事物', 'pron', 'It would take forever for me to explain everything.', '我就算说上三天三夜，恐怕也不能把一切解释清楚。', 'CET4'),
