  ('music', '/''mju:zik/', 'n. 音乐, 乐曲', 'n', 'She likes music. "So do I."', '“她喜欢音乐。”“我也是。”', 'CET4'),
  ('buy', '/bai/', 'vt. 买, 获得 vi. 买 n. 购买, 买得的东西', 'vt', 'It''s a pity that you can''t buy miracles like you would buy potatoes.', '可惜我们不能像买土豆一样买奇迹。', 'CET4'),
