  ('market', '/''mɑ:kit/', 'n. 市场, 交易, 集市, 推销地区, 行情, 市面, 销路 vt. 在市场上交易, 使上市, 销售 vi. 在市场上买卖', 'n', 'Did you buy it on the black market?', '你是在黑市上买的它吗？', 'CET4'),
  ('die', '/dai/', 'vi. 死亡, 消逝, 平息, 熄灭, 漠然, 渴望 vt. 死 n. 骰子, 冲模', 'vi', 'If you don''t eat, you die.', '人不吃东西就会死。', 'CET4'),
  ('send', '/send/', 'vt. 发送, 使进入, 寄, 派遣, 发射, 使陷于 vi. 寄信, 派人, 播送 n. (船的)上升运动 [计] 发送', 'vt', 'I told them to send me another ticket.', '我请他们再寄给我一张票。', 'CET4'),
