  ('stay', '/stei/', 'n. 停留, 逗留, 制止, 延缓, 停止, 支柱, 支撑物, 支索 vt. 制止, 延缓, 坚持, 支持, 支撑, 用支索固定 vi. 停留, 逗留, 暂停, 坚持, 中止', 'n', 'How long did you stay?', '你待了多久?', 'CET4'),
  ('fall', '/fɒ:l/', 'n. 落下, 瀑布, 采伐量, 下降, 落差, 降低, 堕落, 秋天 vi. 倒下, 落下, 来临, 失守, 阵亡, 下跌, 减弱, 倾斜, 垮台, 轮到, 变成, 降低 a. 秋天的', 'n', 'I''m afraid to fall.', '我怕摔倒。', 'CET4'),
  ('england', '/''iŋglәnd/', 'n. 英格兰 [法] 英格兰, 英国', 'n', NULL, NULL, 'CET4'),
