  ('cut', '/kʌt/', 'n. 切口, 割伤, 降低, 切, 割, 砍, 削, 伤口, 削减, 缩短, 删节, 通路 a. 经切割的, 缩减的 vt. 切, 割, 减少, 刺痛, 开辟, 雕刻, 删节, 缩短, 停止, 排斥, 切断, 关, 显出 vi. 切, 割, 砍, 刺痛, 相交, 抄近路, 剪辑 [计] 剪切', 'n', 'We are cut from the same cloth.', '我们很相似。', 'CET4'),
  ('college', '/''kɒlidʒ/', 'n. 学院, 大学, 学会', 'n', 'Our new English teacher is fresh from college.', '我们新的英语老师刚从大学毕业。', 'CET4'),
  ('someone', '/''sʌmwʌn/', 'pron. 有人, 某人', 'pron', 'It is difficult to keep up a conversation with someone who only says "yes" and "no".', '和一个只说"是"与"否"的人维持一段对话是很难的。', 'CET4'),
  ('behind', '/bi''haind/', 'adv. 在后地 prep. 在...背后', 'adv', 'A beautiful valley lies behind the hill.', '小山后面有个美丽的山谷。', 'CET4'),
  ('six', '/siks/', 'num. 六, 六个', 'num', 'At the age of six he had learned to use the typewriter and told the teacher that he did not need to learn to write by hand.', '他六岁的时候学会了用打字机，便和老师说他不用学执笔写字了。', 'CET4'),
  ('suggest', '/sәg''dʒest/', 'vt. 提议, 建议, 促成, 暗示, 启发, 使人想起 [法] 建议, 提出, 提议', 'vt', 'I suggest that we go out on Friday.', '我建议我们星期五出去玩。', 'CET4'),
  ('class', '/klɑ:s/', 'n. 班级, 阶级, 种类, 课 vt. 分类 [计] 类别; 类; 种类; 类程', 'n', 'You never have class or what?!', '你从来没课还是怎样？', 'CET4'),
  ('raise', '/reiz/', 'n. 上升, 高地, 增高 vt. 升起, 举起, 唤起, 提高, 使出现, 使复活, 提出, 筹集, 饲养', 'n', 'The only useful answers are those that raise new questions.', '只有能提出新问题的回答才是有用的回答。', 'CET4'),
  ('care', '/kєә/', 'n. 小心, 照料, 忧虑 vi. 关心, 介意 vt. 在意, 喜欢', 'n', 'My physics teacher doesn''t care if I skip classes.', '我的物理老师不在乎我是否逃课。', 'CET4'),
  ('late', '/leit/', 'a. 迟的, 晚的, 已故的 adv. 很晚, 很迟, 晚', 'adj', 'I was late to school.', '我上学迟到了。', 'CET4'),
  ('hard', '/hɑ:d/', 'a. 坚硬的, 硬的, 难的, 艰苦的, 困难的, 坚固的, 猛烈的, 艰难的, 结实的, 确实的 adv. 坚硬地, 努力地, 辛苦地, 接近地, 猛烈地, 牢固地', 'adj', 'Life is hard, but I am harder.', '生活很困难，但我更坚强。', 'CET4'),
  ('field', '/fi:ld/', 'n. 领域, 田地, 场地, 战场, 场, 域 vt. 使...晒在场上, 使上场 a. 田间的, 野生的, 野外的, 田赛的 [计] 域, 字段', 'n', 'What''s your major field?', '你专攻什么领域？', 'CET4'),
  ('else', '/els/', 'a. 别的, 其他的 adv. 另外, 否则, 不然', 'adj', 'I can only wonder if this is the same for everyone else.', '我只能问自己这对其他所有人是不是一回事呢。', 'CET4'),
  ('pass', '/pæs/', 'n. 经过, 要隘, 途径, 通行, 护照, 及格 vt. 经过, 越过, 通过, 批准, 度过, 传递, 忽略 vi. 经过, 变化, 流通, 及格, 宣判, 终止, 消逝, 被忽略, 不叫牌, 传递 [计] 遍', 'n', 'Pass me the salt, please. "Here you are."', '“请把盐递给我。”“拿着。”', 'CET4'),
  ('sell', '/sel/', 'vt. 卖, 背叛, 销售, 出卖 vi. 卖, 销售 n. 卖, 推销术, 失望', 'vt', 'Investing money in your home has some merit; when it is time to sell it you can get more money.', '多花点钱在房子上，也有一些好处 ﹣ 例如，卖的时候可以卖个比较好的价钱。', 'CET4'),
  ('sometimes', '/''sʌmtaimz/', 'adv. 有时, 时常, 往往', 'adv', 'Blind people sometimes develop a compensatory ability to sense the proximity of objects around them.', '某些失明者会产生一个弥补性的能力，这个能力让他们察觉到他们与离他们很近的物体的距离。', 'CET4'),
  ('along', '/ә''lɒŋ/', 'adv. 平行地, 向前 prep. 沿着', 'adv', 'How is your work coming along?', '你的工作进行得怎么样？', 'CET4'),
  ('development', '/di''velәpmәnt/', 'n. 发展 [化] 展开', 'n', 'The development of the computer industry has been very rapid.', '电脑产业的发展一日千里。', 'CET4'),
  ('themselves', '/ðәm''selvz/', 'pron. 他们自己, 她们自己, 它们自己', 'pron', 'I don''t like it when mathematicians who know much more than I do can''t express themselves explicitly.', '我不喜欢那些数学家知道的比我多得多，却不知道清楚地表达自己。', 'CET4'),
  ('report', '/ri''pɒ:t/', 'n. 报告, 报道, 传说, 案情报告, 爆炸声, 成绩单 vt. 报告, 汇报, 转述, 报道, 揭发, 使报到 vi. 报告, 写报道, 报到 [计] 报告', 'n', 'I prefer to look for a solution to problems, not only to report them.', '我更喜欢寻求问题的解决方法，而不仅仅是揭露它们。', 'CET4'),
  ('decide', '/di''said/', 'v. 决定, 判决', 'v', 'It is up to you to decide whether we will go there or not.', '该由你来决定我们去不去那儿。', 'CET4'),
  ('strong', '/strɒŋ/', 'a. 强壮的, 坚固的, 坚强的, 强烈的, 有力的, 优良的 adv. 强劲地, 有力地, 猛烈地', 'adj', 'The strong wind indicates that a storm is coming.', '强风暗示著即将到来的暴雨。', 'CET4'),
  ('possible', '/''pɒsәbl/', 'a. 可能的, 潜在的, 合适的 n. 可能性, 可能的事物', 'adj', 'She''s asking how that''s possible.', '她问这怎么可能。', 'CET4'),
  ('heart', '/hɑ:t/', 'n. 心, 心脏, 中心, 内心, 感情, 精神, 心情, 宝贝儿 vt. 鼓励', 'n', 'My heart was filled with happiness.', '我心里充满着快乐。', 'CET4'),
  ('light', '/lait/', 'n. 光, 光亮, 灯, 日光, 发光体, 光源, 杰出人物, 火花, 眼光 a. 轻的, 少量的, 轻微的, 轻快的, 轻浮的, 明亮的, 淡色的, 容易的 vt. 点燃, 照亮 vi. 点着, 变亮, 突降, 偶然碰到 adv. 轻地', 'n', 'It''s just five in the morning, but nevertheless it is light out.', '只有早上5点，但天已经亮了。', 'CET4'),
  ('wife', '/waif/', 'n. 妻子, 太太, 夫人 [法] 妻子, 已婚妇女', 'n', 'I heard the manager''s wife is on vacation. And, well, when the cat''s away, the mice play. Now he''s out partying every night.', '我听说经理的妻子出去度假了。这时就是山中无老虎，猴子称大王了。现在经理他夜夜笙箫。', 'CET4'),
  ('mind', '/maind/', 'n. 思想, 愿望, 智力, 记忆, 心理, 情绪, 理智, 主意, 心意 vi. 介意, 注意, 留心 vt. 注意, 留意, 专心于, 照看, 介意', 'n', 'I have too many things on my mind these days.', '这几天我脑袋里的事情太多了。', 'CET4'),
  ('pull', '/pul/', 'vt. 拉, 拖, 拔, 牵, 撕开, 吸引 vi. 拉, 拖, 拔, 有吸引力 n. 拉, 拖, 拔, 拉力, 牵引力, 划船, 吸引', 'vt', 'A whistle blew, and the boat slowly began to pull out of port.', '汽笛声响起，船开始慢慢地驶离港口。', 'CET4'),
  ('return', '/ri''tә:n/', 'n. 回来, 返回, 来回票, 归还, 报答, 利润率, 报告书 a. 返回的, 回程的, 报答的, 反向的, 重现的, 复原的 vi. 返回, 归还, 回来 vt. 归还, 还, 回报, 产生, 反射, 报告, 申报, 退回 [计] 返回', 'n', 'You should return home before it gets dark.', '你应该在天黑之前回家。', 'CET4'),
  ('free', '/fri:/', 'a. 自由的, 享受政治权力的, 允许的, 免费的, 丰富的 vt. 释放, 解放, 使自由 adv. 自由地, 免费', 'adj', 'A democrat is a free citizen who yields to the will of the majority.', '民主主义者是屈服于大部分人的自由公民。', 'CET4'),
  ('price', '/prais/', 'n. 价格, 代价, 价值 vt. 定...的价格', 'n', 'The price of gold varies from day to day.', '金价每天都在变动。', 'CET4'),
  ('son', '/sʌn/', 'n. 儿子, 女婿, 子孙 [法] 儿子, 女婿, 养子', 'n', 'Like father, like son.', '有其父必有其子。', 'CET4'),
  ('hope', '/hәup/', 'n. 希望, 信心, 期待 v. 希望, 期望, 信赖', 'n', 'Hope is not a strategy.', '希望不是一种策略。', 'CET4'),
  ('develop', '/di''velәp/', 'vt. 发展, 使发达, 进步, 洗印, 显影 vi. 发展, 生长', 'vt', 'Blind people sometimes develop a compensatory ability to sense the proximity of objects around them.', '某些失明者会产生一个弥补性的能力，这个能力让他们察觉到他们与离他们很近的物体的距离。', 'CET4'),
  ('carry', '/''kæri/', 'n. 进位, 射程, 运载 vt. 携带, 运送, 支持, 传送, 包含 vi. 被携带, 能达到 [计] 进位; 进位数', 'n', 'Let''s carry on the discussion.', '让我们进行讨论。', 'CET4'),
  ('town', '/taun/', 'n. 城镇, 市, 镇 [法] 城镇, 城市, 闹市', 'n', 'This is the town I told you about.', '这就是我跟你说的那个镇。', 'CET4'),
