  ('drive', '/draiv/', 'n. 驾车, 快车道, 推进力, 驱动, 动力, 击球, 驱动器 vt. 开车, 驱使, 推动, 驾驶 vi. 开车, 猛击, 飞跑 [计] 驱动器', 'n', 'What... you still don''t know how to drive?', '什么。。。？你还是不会开车？', 'CET4'),
  ('arm', '/ɑ:m/', 'n. 手臂, 袖子, 狭长港湾, 武器 vt. 武装, 装备 vi. 武装起来 [计] 异步应答方式; 自动货品销路管理', 'n', 'I have a very sore arm where you hit me.', '你打在我手臂上的地方超级痛。', 'CET4'),
  ('true', '/tru:/', 'a. 真实的, 正确的, 忠诚的, 可靠的, 纯粹的, 正式的 n. 真实, 准确 adv. 真实地, 准确地', 'adj', 'It is unfortunately true.', '可惜这是真的。', 'CET4'),
  ('break', '/breik/', 'n. 休息, 中断, 破裂处, 绝交, 破晓, 突变 vt. 打破, 弄破, 弄坏, 破坏, 违反, 打断, 削弱, 放弃 vi. 破碎, 决裂, 破晓, 突变, 变弱, 暂停 n. 分隔符 [计] 分隔符; 中断; DOS内部命令:设定扫描中断按键的时机', 'n', 'I slept a little during lunch break because I was so tired.', '我在午休时间睡了一会儿，因为我太累了。', 'CET4'),
  ('receive', '/ri''si:v/', 'vt. 收到, 接到, 得到, 接待, 迎接, 承受 vi. 收到, 会客 [计] 接收', 'vt', 'We speak that we do know, and testify that we have seen; and ye receive not our witness.', '我们说我们所知道的，为我们所看到的作证；你们却不接受我们的见证。', 'CET4'),
  ('thank', '/θæŋk/', 'n. 谢意, 感谢 vt. 谢谢, 感谢', 'n', 'Thank you for helping me. "Don''t mention it."', '“谢谢你的帮助。” “不用谢。”', 'CET4'),
  ('building', '/''bildiŋ/', 'n. 建筑物, 建筑 [法] 营造, 建筑, 建筑物', 'n', 'The building on the hill is our school.', '山上的那栋建筑物就是我们的学校了。', 'CET4'),
  ('full', '/ful/', 'n. 全部, 完整 a. 充满的, 完全的, 丰富的, 完美的, 丰满的, 详尽的 adv. 完全地, 整整, 十分 vt. 把(衣服等)缝得宽松, 漂洗 [计] 完整', 'n', 'Why is life so full of suffering?', '为什么生活充满着那么多痛苦?', 'CET4'),
  ('join', '/dʒɒin/', 'vi. 参加, 结合, 加入 vt. 连接, 结合, 参加, 加入 n. 连接, 结合, 接合点 [计] 连接; 汇合指令', 'vi', 'It is a pity that you can''t join us.', '你不能和我们一起来真可惜。', 'CET4'),
  ('season', '/''si:zn/', 'n. 季节, 时节, 当令期, 时期 vt. 给...调味, 使成熟, 使老练, 缓和 vi. 变干燥', 'n', 'Winter is my favorite season.', '冬天是我最喜欢的季节。', 'CET4'),
  ('agree', '/ә''gri:/', 'vi. 同意, 赞成, 应允, 适合 vt. 承认, 认定, 同意', 'vi', 'I don''t agree with him.', '我不同意他。', 'CET4'),
  ('pick', '/pik/', 'n. 精选, 选择, 掘, 精华, 牙签, 鹤嘴锄 v. 摘, 掘, 凿, 挖, 挑选 [计] 拾取', 'n', 'Pick up your things and go away.', '收好你的东西，滚出去。', 'CET4'),
  ('wear', '/wєә/', 'n. 穿着, 戴, 使用, 耗损, 服装, 耐久性 vt. 穿着, 戴, 留(须、发等), 呈现, 磨损, 磨成, 耗损, 使疲乏, 消磨 vi. 磨损, 变旧, 耐久, 渐变, 渐渐消失', 'n', 'What size shoes do you wear?', '你穿几号的鞋子?', 'CET4'),
  ('paper', '/''peipә/', 'n. 纸, 文件, 文章, 报纸, 证券, 证件 vt. 用纸糊, 贴壁纸于, 用纸包装 vi. 贴壁纸 a. 纸做的, 纸上的', 'n', 'I have to write a letter. Do you have some paper?', '我需要写一封信。你有纸吗？', 'CET4'),
  ('ground', '/graund/', 'n. 土地, 战场, 场地, 地面, 范围 a. 土地的, 地面上的 vt. 放在地上, 使搁浅, 打基础, 给...以训练 vi. 搁浅, 落地, 根据, 基于 a. 磨过的 grind的过去式和过去分词', 'n', 'The pirates buried their treasure in the ground.', '海盗把财宝藏进了地底。', 'CET4'),
  ('form', '/fɒ:m/', 'n. 形状, 形体, 类型, 方式, 表格, 形式 v. 形成, 排列, (使)组成 n. 表单 [计] 表单', 'n', 'Democracy is the worst form of government, except all the others that have been tried.', '除了那些我们尝试过的政府形态，民主是最差的那种了。', 'CET4'),
  ('whose', '/hu:z/', 'pron. 谁的', 'pron', 'Whose is this?', '这是谁的？', 'CET4'),
  ('everyone', '/''evriwʌn/', 'pron. 每个人, 人人 [计] 系统中的一个组名', 'pron', 'I can only wonder if this is the same for everyone else.', '我只能问自己这对其他所有人是不是一回事呢。', 'CET4'),
  ('star', '/stɑ:/', 'n. 星, 恒星, 星形物, 运气, 明星 vt. 以星状物装饰, 用星号标, 使成为明星 vi. 变成明星', 'n', 'There was a big gold star on the door.', '在门上有一个大大的金色星星。', 'CET4'),
  ('table', '/''teibl/', 'n. 桌子, 餐桌, 工作台, 铭文, 表格, 表, 高原, 平地层 vt. 搁置, 嵌合, 制表, 把...列入议事日程 [计] 表格, 模拟运算表', 'n', 'Place the deck of cards on the oaken table.', '把扑克牌放在橡木桌上。', 'CET4'),
  ('eat', '/i:t/', 'v. 吃, 腐蚀', 'v', 'If you don''t eat, you die.', '人不吃东西就会死。', 'CET4'),
  ('teach', '/ti:tʃ/', 'vt. 教, 讲授, 教导, 教育 vi. 教书, 教学, 可以教', 'vt', 'I''ll teach you how to drive a car.', '我会教你怎么开车。', 'CET4'),
  ('half', '/hɑ:f/', 'n. 一半, 半场, 不完全 a. 一半的, 不完全的, 部分的, 半场的 adv. 一半地, 部分地, 在某种程度上地, 几乎', 'n', 'Half a million children still face malnutrition in Niger.', '尼日尔仍然有50万孩子面临着营养不良。', 'CET4'),
  ('easy', '/''i:zi/', 'a. 容易的, 缓缓的, 舒适的, 从容的, 宽容的, 流畅的, 随便的, 自在的, 疲软的 adv. 容易地, 慢慢地', 'adj', 'You are working too hard. Take it easy for a while.', '你工作得太辛苦了。放轻松一下。', 'CET4'),
  ('cost', '/kɒst/', 'n. 代价, 价值, 费用 vi. 花费 vt. 使失去, 值, 使花费', 'n', 'This will cost €30.', '这个要三十欧元。', 'CET4'),
  ('street', '/stri:t/', 'n. 街道, 马路, 街区 a. 街道的', 'n', 'It is easier to hit on people on the Internet than in the street.', '在网上勾人比在街上容易。', 'CET4'),
  ('itself', '/it''self/', 'pron. 它本身, 它自己', 'pron', 'The frame itself is worth more than the picture.', '画框比画还值钱。', 'CET4'),
  ('either', '/''i:ðә/', 'a. (两者之中)任一的, (两者之中)各一的 pron. (两者之中)任一 conj. 或, 要么', 'adj', 'I can''t explain it either.', '我也无法解释。', 'CET4'),
  ('europe', '/''juәrәp/', 'n. 欧洲', 'n', NULL, NULL, 'CET4'),
  ('cover', '/''kʌvә/', 'n. 盖子, 封面, 藉口 vt. 覆盖, 掩饰, 保护, 掩护, 包括 vi. 覆盖', 'n', 'Cover your mouth when you cough, sneeze, or yawn.', '你咳嗽、打喷嚏或打哈欠的时候要捂住你的嘴。', 'CET4'),
  ('quite', '/kwait/', 'adv. 相当, 完全, 十分', 'adv', 'Well, the night is quite long, isn''t it?', '夜晚很长，不是吗？', 'CET4'),
  ('picture', '/''piktʃә/', 'n. 图画, 照片, 景色, 美丽如画的人(或物), 化身, 生动的描述, 想像, 形象思维 vt. 画, 拍摄, 用图说明, 描写, 想像 [计] 图象; 形象; 字形', 'n', 'Is it a recent picture?', '那是一张近照吗？', 'CET4'),
  ('clear', '/kliә/', 'a. 清楚的, 明确的, 澄清的 adv. 清晰地 vt. 澄清, 清除障碍 vi. 放晴, 变清澈 n. 空隙 [计] 清除', 'adj', 'You must clear the table.', '你必须把桌子清理干净。', 'CET4'),
  ('practice', '/''præktis/', 'n. 实践, 练习, 实行, 惯例, 习惯, 开业 v. 实践, 实行, 练习, 实习, 业务', 'n', 'In theory, there is no difference between theory and practice. But, in practice, there is.', '理论上说，理论和实践没有区别。但实践上说，是有的。', 'CET4'),
  ('piece', '/pi:s/', 'n. 块, 片, 篇, 碎片, 部分, 部件, 标准量 vt. 修补, 修理, 拼合, 接线头 vi. 吃零食', 'n', 'I want a piece of candy.', '我想要一颗糖。', 'CET4'),
  ('land', '/lænd/', 'n. 陆地, 地面, 地界, 地产, 国土, 土地 vi. 登陆, 登岸, 到达 vt. 使上岸, 使登陆, 使到达 [计] 连接盘; 焊盘', 'n', 'Tomorrow, he will land on the moon.', '明天，他将登上月球。', 'CET4'),
  ('doctor', '/''dɒktә/', 'n. 医生, 博士 vt. 授以博士学位, 诊断, 修改 vi. 行医', 'n', 'You''d better consult the doctor.', '您最好请教一下医生。', 'CET4'),
  ('wall', '/wɒ:l/', 'n. 墙, 墙壁, 垣, 内壁, 分界物, 屏障 a. 墙的 vt. 给...建墙, 禁闭, 用墙围住 [计] 背景墙', 'n', 'We were driven to the wall.', '我们被逼得走投无路了。', 'CET4'),
  ('worker', '/''wә:kә/', 'n. 工人, 劳动者 [经] 工人, 劳工, 劳动者', 'n', 'You''re really a hard worker.', '你真是个努力的工人。', 'CET4'),
  ('news', '/nju:z/', 'n. 新闻, 消息, 报导 [法] 新闻, 消息, 新闻报导', 'n', 'The news article painted the defendant as a guilty man, even though he had been proven innocent.', '该报文章中将被告人描述成一个罪魁祸首，尽管他已经被证明是无辜的了。', 'CET4'),
  ('north', '/nɒ:θ/', 'n. 北方, 北 a. 北的, 北方的 adv. 向北方, 在北方', 'n', NULL, NULL, 'CET4'),
  ('third', '/θә:d/', 'num. 第三, 三分之一 [机] 第三; 第三的', 'num', 'One third of the earth''s surface is desert.', '地球表面的三分之一是沙漠。', 'CET4'),
  ('catch', '/kætʃ/', 'n. 捕捉, 陷阱, 捕捉之物, 抓, 拉手 vt. 捕捉, 赶上, 感染, 听清楚 vi. 抓住, 燃着', 'n', 'You will not be able to catch the train.', '你将无法赶上火车。', 'CET4'),
  ('baby', '/''beibi/', 'n. 婴孩 [医] 婴儿', 'n', 'This baby penguin is too cute!', '这只企鹅宝宝太可爱了！', 'CET4'),
  ('computer', '/kәm''pju:tә/', 'n. 电脑, 电子计算机 [计] 计算机', 'n', 'So annoying... Now I get a headache whenever I use the computer!', '好烦……现在我只要一用电脑就会头痛！', 'CET4'),
  ('draw', '/drɒ:/', 'vi. 拉, 拖, 拔剑 vt. 拖拉, 挨近, 领取, 打成平局, 引导, 抽签决定, 画, 描写, 制订, 草拟, 吸引 n. 拉, 拖, 拔出, 抽签, 平局 [计] 翻牌, 绘图', 'vi', 'Draw a circle.', '画一个圈。', 'CET4'),
  ('film', '/film/', 'n. 软片, 薄膜, 胶卷, 电影 vt. 覆以薄膜, 拍摄 vi. 生薄膜, 拍电影', 'n', 'The film lasted 2 hours.', '电影持续了2个小时。', 'CET4'),
  ('tree', '/tri:/', 'n. 树, 木料, 树状物 vt. 把...赶上树 [计] 树; DOS外部命令:显示指定磁盘驱动器的目录结构', 'n', 'It is easy for a monkey to climb a tree.', '对猴子来说，爬树很容易。', 'CET4'),
  ('red', '/red/', 'a. 红的, 红色的, 红肿的, 流血的 n. 红色, 红颜料, 赤字 [计] 简化, 减少', 'adj', 'The victim of blackmail has been paying hush money for years, but now he realizes it is foolish, and has decided not to pay a red cent more.', '被害人被勒索支付封口费已经很多年, 但现在他意识到这样做是愚蠢的, 而且他已经决定再也不付一毛钱了。', 'CET4');;

INSERT INTO `word_dictionary` (`word`, `phonetic`, `translation`, `pos`, `example`, `example_translation`, `level`) VALUES
  ('nearly', '/''niәli/', 'adv. 几乎, 密切地', 'adv', 'When I ask people what they regret most about high school, they nearly all say the same thing: that they wasted so much time.', '当我问人家高中时代他们最后悔的是什么时，他们几乎所有人都回答一致：他们浪费了那么多时间。', 'CET4'),
  ('hair', '/hєә/', 'n. 头发, 毛发, 些微 [医] 毛, 发', 'n', 'Maria has long hair.', '玛丽亚有一头长发。', 'CET4'),
  ('window', '/''windәu/', 'n. 窗户, 窗子, 窗口 vt. 给...开窗 [计] 窗口', 'n', 'We could see the sunset from the window.', '我们能从窗户看到日落。', 'CET4'),
  ('difficult', '/''difikәlt/', 'a. 困难的', 'adj', 'It is difficult to keep up a conversation with someone who only says "yes" and "no".', '和一个只说"是"与"否"的人维持一段对话是很难的。', 'CET4'),
  ('listen', '/''lisn/', 'vi. 听, 倾听, 听从 n. 听, 倾听', 'vi', 'Don''t listen to him, he''s talking nonsense.', '别听他的, 他在说废话。', 'CET4'),
  ('soon', '/su:n/', 'adv. 不久, 早, 快, 宁可', 'adv', 'I will be back soon.', '我很快就会回来。', 'CET4'),
  ('brother', '/''brʌðә/', 'n. 兄弟', 'n', 'My little brother is watching TV.', '我弟弟在看电视。', 'CET4'),
  ('summer', '/''sʌmә/', 'n. 夏季, 全盛时期 vi. 避暑, 过夏天 [计] 加法器', 'n', 'During summer breaks, I ate dinner at midnight.', '暑假里，我半夜十二点才吃晚饭。', 'CET4'),
  ('hundred', '/''hʌndrәd/', 'n. 百, 百个东西 num. 百, 百个 a. 一百的, 许多的', 'n', 'One hundred and fifty thousand couples are expected to get married in Shanghai in 2006.', '预计2006年15万对夫妇将会在上海结婚。', 'CET4'),
  ('plant', '/plænt. plɑ:nt/', 'n. 植物, 作物, 工厂, 树枝, 生长, 设施, 成套设备 vt. 种植, 栽培, 播种, 培养, 安置, 殖民于, 使位于 vi. 种植', 'n', 'Pull the plant up by the roots.', '从根部把植物拔出来。', 'CET4'),
  ('short', '/ʃɒ:t/', 'a. 短的, 近的, 矮的, 短期的, 简短的, 少量的 adv. 简短地, 突然 n. 扼要, 短片, 缺乏 vt. 故意少给, 使短路', 'adj', 'A rabbit has long ears and a short tail.', '兔子有长耳朵和短尾巴。', 'CET4'),
  ('letter', '/''letә/', 'n. 信, 字母, 证书, 字面意义, 铅字, 学问, 出租人 vt. 写字母于, 在...上刻字母, 用字母标明 vi. 写印刷体字 [计] 字母', 'n', 'I have to write a letter. Do you have some paper?', '我需要写一封信。你有纸吗？', 'CET4'),
  ('single', '/''siŋgl/', 'a. 单身的, 单程的, 单一的, 个别的, 孤独的, 专一的 n. 一个, 单打, 单程票 vt. 选出 vi. 击出一垒打 [计] 单精度型', 'adj', 'There isn''t a single cloud in the sky.', '天上没有一片云。', 'CET4'),
  ('daughter', '/''dɒ:tә/', 'n. 女儿 a. 女儿的', 'n', 'The prince fell in love with a woodcutter''s daughter.', '王子爱上了一个樵夫的女儿。', 'CET4'),
  ('south', '/sauθ/', 'n. 南方, 南 a. 南的, 向南的 adv. 在南方 vi. 转向南方', 'n', 'France is to the south of England.', '法国在英国的南边。', 'CET4'),
  ('husband', '/''hʌzbәnd/', 'n. 丈夫, 管理人, 节俭的人 vt. 节俭, 使成丈夫, 持有', 'n', 'The accident bereaved her of her husband.', '事故使她失去了丈夫。', 'CET4'),
  ('floor', '/flɒ:/', 'n. 地板, 楼层, 底部, 底价 vt. 铺地板, 打倒 n. 地面, 地板, 基底 [计] 基底', 'n', 'Your glasses fell on the floor.', '你的眼镜掉在地上了。', 'CET4'),
  ('colour', '/''kʌlә/', 'n. 颜色, 面色, 颜料, 外貌 vt. 把...涂上颜色, 粉饰, 使脸红, 歪曲 vi. 变色', 'n', 'Many Chinese people consider red to be the best colour.', '很多中国人认为红色是最好的颜色。', 'CET4'),
  ('hospital', '/''hɒspitәl/', 'n. 医院 [医] 医院', 'n', 'We have to take him to the hospital immediately; he is seriously injured!', '我们要赶紧把他送去医院，他伤得很严重！', 'CET4'),
  ('close', '/klәuz/', 'n. 结束, 完结 a. 靠近的, 亲近的, 亲密的, 严密的, 关闭的, 狭窄的, 秘密的 vt. 关, 结束, 使靠近, 封闭, 使接近 vi. 关闭, 结束, 靠近 adv. 接近地, 紧密地 [计] 关闭', 'n', 'Close the door when you leave.', '出去的时候把门关上。', 'CET4'),
  ('thousand', '/''θauznd/', 'num. 千 a. 成千的, 许多的 n. 许许多多', 'num', 'One hundred and fifty thousand couples are expected to get married in Shanghai in 2006.', '预计2006年15万对夫妇将会在上海结婚。', 'CET4'),
  ('fire', '/''faiә/', 'n. 火, 炉火, 电炉, 火灾, 闪光体, 炮火, 热情 vt. 点燃, 烧制, 使发光, 激动, 放枪, 解雇 vi. 着火, 烧火, 开枪, 射击, 激动', 'n', 'Did you hear about the fire yesterday?', '你听说了昨天的火灾吗?', 'CET4'),
  ('future', '/''fju:tʃә/', 'n. 未来, 将来 a. 将来的, 未来的', 'n', 'The past can only be known, not changed. The future can only be changed, not known.', '我们可以回顾过去，但不能改变过去；我们可以改变未来，但不能预知未来。', 'CET4'),
  ('wrong', '/rɒŋ/', 'a. 错误的, 不正当的, 失常的 adv. 错误地', 'adj', 'You took the wrong key.', '你拿错钥匙了。', 'CET4'),
  ('myself', '/mai''self/', 'pron. 我自己, 我亲自, 我独自', 'pron', 'I''d be unhappy, but I wouldn''t kill myself.', '我会不高兴，但我不会自杀。', 'CET4'),
  ('bank', '/bæŋk/', 'n. 银行, 堤, 岸 [医] 库', 'n', 'You can get a loan from a bank.', '你可以从银行贷款。', 'CET4'),
  ('west', '/west/', 'n. 西方, 西部 a. 西方的, 向西的 adv. 向西, 自西方, 在西方', 'n', 'Even if the sun were to rise in the west, I would not change my mind.', '即使太阳从西边出来，我也不会改变主意。', 'CET4'),
  ('sport', '/spɒ:t/', 'n. 运动, 游戏, 娱乐, 消遣, 玩笑 a. 运动的, 户外穿戴的 vi. 游戏, 参加体育运动, 戏弄, 产生变种 vt. 炫耀, 使产生变种', 'n', 'Boxing is not always a rough sport.', '拳击并不总是一种粗暴的运动。', 'CET4'),
  ('rest', '/rest/', 'n. 休息, 睡眠, 安息, 稍息, 静止, 支架, 休息处, 其余者, 剩余部分 vi. 休息, 睡, 长眠, 安心, 静止, 停止, 安置, 依赖 vt. 使休息, 使支撑, 把...寄托于', 'n', 'You''re sick. You have to rest.', '你病了，该休息了。', 'CET4'),
  ('throw', '/θrәu/', 'vt. 投, 掷, 抛, 发射, 摔下, 匆匆穿上(或脱下), 抛弃, 摆脱 vi. 丢, 掷, 抛 n. 投掷, 掷骰子, 冒险', 'vt', 'Throw a sprat to catch a whale.', '丢鲱鱼抓鲸鱼。', 'CET4'),
  ('past', '/pɑ:st/', 'n. 过去, 昔时, 往事, 早年经历, 过去时 a. 过去的, 结束的, 卸任的, 过去时的 prep. 越过, 晚于, 超越, 超出...的可能性(能力、范围等) pass的过去分词', 'n', 'The past can only be known, not changed. The future can only be changed, not known.', '我们可以回顾过去，但不能改变过去；我们可以改变未来，但不能预知未来。', 'CET4'),
  ('bed', '/bed/', 'n. 床, 睡眠处, 河床, 底座, 路基, 一层 vt. 提供宿处, 栽种, 安装 vi. 睡, 形成坚实的一层', 'n', 'I have to go to bed.', '我该去睡觉了。', 'CET4'),
  ('april', '/''eiprәl/', 'n. 四月', 'n', NULL, NULL, 'CET4'),
  ('order', '/''ɒ:dә/', 'n. 次序, 规则, 命令 vi. 命令, 定货 vt. 整理, 命令, 定购 n. 顺序, 阶数 [计] 顺序, 阶数', 'n', 'In order to do that, you have to take risks.', '要这么做，你需要冒险。', 'CET4'),
  ('fill', '/fil/', 'vt. 装满, 填充, 弥漫, 供给, 满足, 供应 vi. 充满, 变得沉重 n. 满足, 装满, 充分, 填方 vt. 填充 vi. 填充 [计] 填充', 'vt', 'Fill in the blanks with suitable words.', '请在空格上填上适当的字词。', 'CET4'),
  ('foreign', '/''fɒ:rin/', 'a. 外国的, 外交的, 外省的, 外来的, 不相关的 [机] 外来的', 'adj', 'Foreign people intrigue me.', '外国人很有意思。', 'CET4'),
  ('june', '/dʒu:n/', 'n. 六月', 'n', NULL, NULL, 'CET4'),
  ('push', '/puʃ/', 'n. 推, 推动, 奋斗, 攻击, 进取心 vt. 推, 推动, 使伸出, 推行, 逼迫, 增加 vi. 推, 推进, 增加, 努力争取', 'n', 'In case of fire, break the glass and push the red button.', '万一发生火灾，打碎玻璃并按下红色按钮。', 'CET4'),
  ('store', '/stɒ:/', 'n. 商店, 贮藏, 仓库, 备用品, 存储器 vt. 储存, 贮藏, 供给 vi. 贮藏 a. 贮藏的, 现成的 [计] 存储器操作; 存储', 'n', 'Please tell us where there is a grocery store.', '请告诉我们哪儿有食品杂货店。', 'CET4'),
  ('sound', '/saund/', 'n. 声音, 语音, 吵闹, 声调, 听力范围, 探条, 海峡 a. 健全的, 可靠的, 合理的, 健康的, 彻底的, 资金充实的 adv. 彻底地, 充分地 vi. 发出声音, 回响, 测深, 试探, 听起来 vt. 使发声, 宣告, 听诊, 测...深, 试探 [计] 声音', 'n', 'It might sound far-fetched, but this is a real problem.', '这可能听起来牵强，但却是个真实的问题。', 'CET4'),
  ('note', '/nәut/', 'n. 笔记, 记录, 注解, 票据, 符号, 显要, 注重, 便笺, 照会 vt. 记录, 注解, 注意', 'n', 'He slipped me a note.', '他悄悄地递给我一张纸条。', 'CET4'),
  ('fine', '/fain/', 'n. 罚款, 罚金, 晴天, 精细 a. 好的, 晴朗的, 健康的, 细小的, 精细的 vt. 罚款, 精炼, 澄清 vi. 变清, 变细 adv. 很好 [计] 精细', 'n', 'You''re by my side; everything''s fine now.', '你在我旁边，现在一切都好了。', 'CET4'),
  ('near', '/niә/', 'a. 近的, 近亲的, 近似的 adv. 接近, 亲近 prep. 靠近, 近似于 v. 接近, 走近', 'adj', 'Is there a youth hostel near here?', '附近有没有青年旅舍？', 'CET4'),
  ('page', '/peidʒ/', 'n. 页, 记录, 事件, 专栏, 男侍 vt. 标明...的页数, 翻...的书页, 分页排版, 呼叫, 侍候 vi. 翻书页, 侍侯 [计] 页; 页面', 'n', 'More than 90 percent of visits to a web page are from search engines.', '一个网页超过百分之九十的访问量是来自于搜索引擎的。', 'CET4'),
  ('poor', '/puә. pɒ:/', 'a. 贫穷的, 贫乏的, 不幸的, 可怜的, 拙劣的, 卑鄙的 [经] 低劣的, 不良的', 'adj', 'Poor is not the one who has too little, but the one who wants too much.', '贫穷的不是拥有太少的人，而是想要太多的人。', 'CET4'),
