  ('hotel', '/hәu''tel/', 'n. 旅馆, 客栈', 'n', 'How far is it from the airport to the hotel?', '从机场到旅馆多远？', 'CET4'),
  ('soldier', '/''sәuldʒә/', 'n. 军人, 士兵, 兵蚁 vi. 从军, 尽职, 偷懒, 磨洋工', 'n', 'The soldier gave water to me.', '士兵给了我水。', 'CET4'),
  ('heavy', '/''hevi/', 'a. 重的, 巨大的, 沉重的, 笨重的, 过度的 adv. 沉重地 n. 重物, 严肃角色', 'adj', 'I''m glad we didn''t go there because there were some localized heavy rain showers.', '我很庆幸我们没有去那儿，因为当时那儿有局部大暴雨。', 'CET4'),
  ('bag', '/bæg/', 'n. 袋子, 袋状物 vt. 使膨大, 装袋, 猎获', 'n', 'On May 18, a young Japanese couple was arrested after their one-year-old baby was found wrapped in a plastic bag and dumped in a gutter.', '一对年轻日本夫妇，把一岁大的亲生婴儿放进胶袋，弃置于排水沟中，于五月十八日被捕。', 'CET4'),
  ('sing', '/siŋ/', 'vi. 唱, 唱歌, 演唱, 鸣, 啼 vt. 唱, 歌颂 n. 嗖嗖声', 'vi', 'Are you going to sing here?', '你们要在这里唱歌吗？', 'CET4'),
  ('surface', '/''sә:fis/', 'n. 面, 表面, 水面, 外表, 平面 a. 表面的, 外观的, 肤浅的, 水面上的 vt. 使成平面, 使浮出水面 vi. 浮出水面, 呈现, 在地面上工作', 'n', 'One third of the earth''s surface is desert.', '地球表面的三分之一是沙漠。', 'CET4'),
  ('realise', '/''riәlaiz,''ri:-/', 'vt. 实现, 认识到, 体会到, 了解, 认清, 使显得逼真, 变卖财产为现钱', 'vt', 'He doesn''t realise that he''s tone deaf.', '他不知道他自己五音不全。', 'CET4'),
  ('whom', '/hu:m/', 'pron. 谁', 'pron', 'Whom are you speaking of?', '你是指谁？', 'CET4'),
  ('machine', '/mә''ʃi:n/', 'n. 机器, 机械装置, 机构, 自动售货机, 机械般工作的人 vt. 以机器制造', 'n', 'The brain is just a complicated machine.', '大脑只是个复杂的机器。', 'CET4'),
  ('beat', '/bi:t/', 'n. 心跳(声), 打, 敲打声, 拍子 v. 打, 拍打, 打败 a. 疲乏的, 颓废的 beat的过去式 [计] 拍; 节拍', 'n', 'He won''t beat me.', '他不会打倒我的。', 'CET4'),
  ('garden', '/''gɑ:dn/', 'n. 花园, 果园, 菜园 vi. 栽培花木 vt. 造园 a. 花园的, 普通的', 'n', 'Her garden is a work of art.', '她的花园是一件艺术作品。', 'CET4'),
  ('modern', '/''mɒdәn/', 'n. 现代人, 有思想的人 a. 现代的, 时髦的', 'n', 'Modern travel enables us to go around the world in a few days.', '现代交通使我们能在几天内环绕地球。', 'CET4'),
  ('kitchen', '/''kitʃin/', 'n. 厨房, 全套炊具 [医] 厨房', 'n', 'Mary went down to the kitchen.', '玛丽下楼到厨房。', 'CET4'),
  ('wish', '/wiʃ/', 'n. 希望, 愿望, 祝愿, 命令, 请求 vt. 愿, 想要, 希望, 祝愿 vi. 希望', 'n', 'I wish I could go to Japan.', '我非常希望能够去日本。', 'CET4'),
  ('agreement', '/ә''gri:mәnt/', 'n. 同意, 合约, 协议 [经] 契约, 协议, 协定', 'n', 'There is not one person who is in agreement with the plan.', '赞成计划的人一个也没有。', 'CET4'),
  ('november', '/nәu''vembә/', 'n. 十一月', 'n', NULL, NULL, 'CET4'),
  ('december', '/di''sembә/', 'n. 十二月', 'n', NULL, NULL, 'CET4'),
  ('mouth', '/mauθ/', 'n. 嘴, 口, 口腔, 口状物 vi. 装腔作势说话, 做鬼脸 vt. 说出, 做作地说', 'n', 'Open your mouth!', '把嘴张开！', 'CET4'),
  ('nor', '/nɒ:/', 'conj. 也不, 也没有 [计] 或非', 'conj', 'No love is foul nor prison fair.', '没有肮脏的爱情, 也没有美丽的监狱。', 'CET4'),
  ('newspaper', '/''nju:z.peipә/', 'n. 报纸', 'n', 'We should read the newspaper so as not to lag behind the times.', '我们应该读报纸，不落后于时代。', 'CET4'),
  ('smile', '/smail/', 'n. 微笑, 喜色, 笑容 vi. 微笑, 觉得好笑 vt. 微笑着表示', 'n', 'Your smile always makes me happy.', '看见你笑，我就会高兴起来。', 'CET4'),
  ('interesting', '/''intristiŋ/', 'a. 有趣的', 'adj', 'It seems interesting to me.', '在我看来很有意思！', 'CET4'),
  ('rich', '/ri:tʃ/', 'a. 富裕的, 富饶的, 浓厚的, 贵重的', 'adj', 'I know you are rich.', '我知道你很有钱。', 'CET4'),
  ('dinner', '/''dinә/', 'n. 晚餐, 正餐, 宴会', 'n', 'During summer breaks, I ate dinner at midnight.', '暑假里，我半夜十二点才吃晚饭。', 'CET4'),
  ('western', '/''westәn/', 'n. 西方人, 西部片, 西部小说 a. 向西方的, 来自西方的, 西方的, 西洋的, 西部的', 'n', 'Japan needed contact with the Western countries.', '日本有必要和西方各国接触。', 'CET4'),
  ('travel', '/''trævl/', 'n. 旅行, 游历, 行进 vi. 旅行, 行进, 移动, 被传播 vt. 旅行, 通过, 使移动', 'n', 'I don''t have anyone who''d travel with me.', '我没有一个愿意跟我一起旅行的人。', 'CET4'),
  ('none', '/nʌn/', 'adv. 一点也不, 毫不 pron. 没有人, 无一物, 并无一个 a. 没有的', 'adv', 'It''s none of your business.', '这不关你的事。', 'CET4'),
  ('front', '/frʌnt/', 'n. 前面, 开头, 前线, 阵线, 态度 vt. 面对, 朝向, 对抗 vi. 朝向', 'n', 'All of a sudden, three dogs appeared in front of us.', '突然之间，三只狗出现在我们面前。', 'CET4'),
  ('wind', '/wind/', 'n. 风, 气息, 气味, 呼吸, 风声, 趋势, 空谈, 卷绕, 弯曲 vt. 使通风, 嗅出, 使喘气, 吹号角, 上发条, 缠绕, 包, 绞起, 吊起, 使弯曲, 使迂回 vi. 嗅出猎物, 吹响号角, 卷曲, 蜿蜒, 迂回, 缠绕', 'n', 'Someday I''ll run like the wind.', '有一天，我会跑得像风一样快。', 'CET4'),
  ('key', '/ki:/', 'n. 钥匙, 键, 解答, 关键, 要害, 基调, 线索, 答案, 暗礁 vt. 调音, 锁上, 提供线索 vi. 使用钥匙 [计] 键, 密钥', 'n', 'You took the wrong key.', '你拿错钥匙了。', 'CET4'),
  ('fast', '/fɑ:st/', 'a. 快速的, 紧的 adv. 很快地, 紧紧地, 彻底地 n. 绝食, 斋戒 vi. 绝食, 斋戒', 'adj', 'You''re not fast enough.', '你不够快。', 'CET4'),
  ('restaurant', '/''restәrɒŋ/', 'n. 餐馆, 饭店', 'n', 'I found that restaurant by accident.', '我偶然发现了那家餐馆。', 'CET4'),
  ('bird', '/bә:d/', 'n. 鸟, 羽毛球 vi. 打鸟', 'n', 'The early bird catches the worm.', '早起的鸟儿有虫吃。', 'CET4'),
  ('corner', '/''kɒ:nә/', 'n. 角落, 转角, 窘境 vt. 迫至一隅, 垄断, 使陷入绝境 vi. 相交成角, 垄断 [计] 边角', 'n', 'There''s a pub just around the corner.', '在转角有一家酒吧。', 'CET4'),
  ('sky', '/skai/', 'n. 天空, 天色, 天堂 vt. 击向空中, 挂在高处 vi. 高涨', 'n', 'Do you ever dream about flying through the sky?', '你曾经梦想在天空飞翔吗？', 'CET4'),
  ('plane', '/plein/', 'n. 平面, 扁平物, 机翼, 飞机, 水准, 地位 a. 平的, 平面的 vt. 将...刨平, 刨平, 掠过水面 vi. 翱翔, 乘飞机旅行, 刨掉', 'n', 'In culture, they are on the same plane as savages.', '在教养上，他们可以说是和野蛮人差不多。', 'CET4'),
  ('nobody', '/''nәubɒdi/', 'n. 小人物, 无名小卒 pron. 无人, 没有人', 'n', 'Nobody understands me.', '没有人理解我。', 'CET4'),
  ('nine', '/nain/', 'num. 九, 九个', 'num', 'You must come back before nine o''clock.', '你必须在九点之前回来。', 'CET4'),
  ('saturday', '/''sætәdi/', 'n. 星期六', 'n', NULL, NULL, 'CET4'),
  ('perfect', '/''pә:fikt/', 'n. 完成时 a. 完美的, 完好的, 理想的, 熟练的, 精确的, 完成式的 vt. 使完美, 修改, 使精通, 改善, 使熟练', 'n', 'To be perfect she lacked just one defect.', '要变得完美，她就是少了一个缺点。', 'CET4'),
  ('conversation', '/.kɒnvә''seiʃәn/', 'n. 会话, 说话, 交谈 [法] 交谈, 社交, 性交', 'n', 'It is difficult to keep up a conversation with someone who only says "yes" and "no".', '和一个只说"是"与"否"的人维持一段对话是很难的。', 'CET4'),
  ('please', '/pli:z/', 'adv. 请 vt. 使高兴, 合...的心意, 取悦 vi. 使人满意, 讨好, 愿意, 敬请', 'adv', 'Please don''t cry.', '请你不要哭。', 'CET4'),
  ('sleep', '/sli:p/', 'n. 睡眠, 静止, 昏迷, 麻木, 长眠, 冬眠 vi. 睡觉, 睡眠, 静止 vt. 睡', 'n', 'I have to go to sleep.', '我该去睡觉了。', 'CET4'),
  ('february', '/''februәri/', 'n. 二月', 'n', NULL, NULL, 'CET4'),
  ('afternoon', '/''ɑ:ftә''nu:n/', 'n. 午后, 下午', 'n', 'Judging from the look of the sky, it may rain this afternoon.', '从天色上判断，今天下午可能会下雨。', 'CET4'),
  ('weekend', '/''wi:kend/', 'n. 周末, 周末休假', 'n', 'She got sick this weekend.', '她周末病倒了。', 'CET4'),
  ('date', '/deit/', 'n. 日期, 约会, 枣椰树 vt. 约会, 定日期 vi. 注明日期, 过时', 'n', 'Mick killed time by reading a magazine while waiting for his date.', 'Mick等待约会的时候靠读杂志打发时间。', 'CET4'),
  ('sorry', '/''sɒri/', 'a. 难过的, 悲哀的, 遗憾的', 'adj', 'I''m sorry, I can''t stay long.', '对不起，我不能待很久。', 'CET4'),
  ('chinese', '/tʃai''ni:z/', 'n. 中文, 中国话, 中国人 a. 中国的, 中国话的', 'n', NULL, NULL, 'CET4'),
  ('ship', '/ʃip/', 'n. 船, 舰 vt. 以船运送, 装船, 运送 vi. 上船, 乘船', 'n', 'Which goes faster, a ship or a train?', '船和火车哪个跑得快？', 'CET4'),
  ('driver', '/''draivә/', 'n. 驾驶员, 驱动器, 驱动程序 [化] 驱动器', 'n', 'The driver increased his speed.', '司机加了速。', 'CET4'),
  ('ice', '/ais/', 'n. 冰, 冰淇淋, 糖衣, 冷若冰霜, 矜持, 贿赂 vt. 使结冰, 冰镇, 覆以糖衣 vi. 结冰', 'n', 'You shouldn''t have eaten so much ice cream.', '你不应该吃这么多冰淇淋。', 'CET4'),
  ('boat', '/bәut/', 'n. 船 vi. 乘船 vt. 以船运', 'n', 'I want a boat that will take me far away from here.', '我想要一艘船带我远离这里。', 'CET4'),
  ('drink', '/driŋk/', 'n. 饮料, 酒 v. 喝, 喝酒', 'n', 'Would you like something to drink?', '你想要什么喝的吗？', 'CET4'),
  ('sun', '/sʌn/', 'n. 太阳, 日, 日光, 阳光 vt. 晒 vi. 晒太阳', 'n', 'The sun rose from the sea.', '太阳从海上升起了。', 'CET4'),
  ('mountain', '/''mauntin/', 'n. 山, 山脉, 大堆', 'n', 'We headed for the mountain cottage.', '我们向山间小屋走去。', 'CET4'),
  ('winter', '/''wintә/', 'n. 冬季, 萧条期, 衰退期 a. 冬天的 vt. 使度过冬天 vi. 过冬', 'n', 'Winter is my favorite season.', '冬天是我最喜欢的季节。', 'CET4'),
  ('village', '/''vilidʒ/', 'n. 村庄 a. 乡村的, 村庄的', 'n', 'To my surprise, there were no people in the village.', '奇怪的是，村子里竟然一个人也没有。', 'CET4'),
  ('farm', '/fɑ:m/', 'n. 农场, 农田 vt. 耕种 vi. 种田', 'n', 'George works on a big farm.', '乔治在一个大农场上工作。', 'CET4'),
  ('european', '/.juәrә''pi:әn/', 'n. 欧洲人 a. 欧洲的, 欧洲人的', 'n', NULL, NULL, 'CET4'),
  ('horse', '/hɒ:s/', 'n. 马, 骑兵, 脚架 vi. 骑马, 取笑 vt. 使骑马, 系马于', 'n', 'Can you ride a horse?', '您会骑马吗？', 'CET4'),
  ('ride', '/raid/', 'n. 骑马, 乘坐, 乘车, 搭便车 vt. 骑, 乘坐, 压迫, 控制 vi. 骑马, 乘车, 漂游', 'n', 'Can you ride a horse?', '您会骑马吗？', 'CET4'),
  ('text', '/tekst/', 'n. 文本, 正文, 课文, 主题, 圣经文句, 乐谱 [计] 电文; 文本; 正文', 'n', 'Do we already have that text?', '我们已经有那篇课文了吗？', 'CET4'),
  ('quick', '/kwik/', 'a. 快的, 迅速的, 敏捷的, 灵敏的, 急速的 adv. 快 n. 新长出的肉, 要害, 核心, 感觉敏锐部位', 'adj', 'There''s enough time for a quick snack.', '有足够的时间很快地吃一下点心。', 'CET4'),
  ('bright', '/brait/', 'a. 明亮的, 聪明的, 鲜明的, 欢快的 adv. 明亮地, 欢快地', 'adj', 'Bright ideas never occur to me.', '我总想不出什么好点子。', 'CET4'),
  ('guest', '/gest/', 'n. 客人, 来宾, 旅客 [化] 客体', 'n', 'Be my guest.', '做我的客人吧。', 'CET4'),
  ('lesson', '/''lesn/', 'n. 课, 课业, 教训', 'n', 'Resignation is the first lesson of life.', '辞职是人生的第一课。', 'CET4'),
  ('river', '/''rivә/', 'n. 河, 江 [法] 河流, 江河, 内河', 'n', 'Seen from the sky, the river looked like a huge snake.', '从天上看下来，这条河像一条巨蛇。', 'CET4'),
  ('photo', '/''fәutәu/', 'n. 相片, 照片, 逼真的描绘 v. 照相 a. 照相的, 摄影用的, 详细记录的, 逼真的, 酷似的', 'n', 'When you''re beginning to look like the photo in your passport, you should go on a holiday.', '当我们开始像自己护照上的照片时，我们该去度假了。', 'CET4'),
  ('tomorrow', '/tә''mɒ:rәu/', 'n. 明天, 未来 adv. 明天, 未来地', 'n', 'I''ll call them tomorrow when I come back.', '我明天回来的时候会跟他们联络。', 'CET4'),
  ('ear', '/iә/', 'n. 耳朵, 倾听, 听觉, 穗 vi. 抽穗', 'n', 'How many people do you think have an ear for music?', '你觉得有多少人懂得欣赏音乐？', 'CET4'),
  ('shop', '/ʃɒp/', 'n. 商店, 工厂, 车间 vi. 购物, 到处寻找 vt. 选购', 'n', 'There is a flower shop near by.', '附近有一家花店。', 'CET4'),
  ('jump', '/dʒʌmp/', 'n. 跳跃, 跳动, 暴涨, 惊跳 vt. 跳跃, 跃过, 突升, 使跳跃 vi. 跳跃, 跳, 跳动, 暴涨 [计] 转移, 跳转', 'n', 'How high can you jump?', '您能跳多高？', 'CET4');;

INSERT INTO `word_dictionary` (`word`, `phonetic`, `translation`, `pos`, `example`, `example_translation`, `level`) VALUES
  ('fit', '/fit/', 'n. 适宜, 合身, 发作, 痉挛 a. 适宜的, 对的, 准备好的 vt. 适合, 安装, 使合身, 使适应, 使合格 vi. 适合, 符合, 合身 [计] 非特', 'n', 'I''m feeling fit.', '我觉得精神很好。', 'CET4'),
  ('cry', '/krai/', 'n. 叫声, 哭声, 大叫 vi. 哭, 叫, 喊 vt. 叫喊, 大声说, 哭出', 'n', 'Seriously though, episode 21 made me almost cry while laughing.', '但是说真的，第21集让我笑得眼泪都要出来了。', 'CET4'),
  ('worth', '/wә:θ/', 'n. 价值, 财产 a. 值...的, 值得的', 'n', 'Kyoto is worth visiting.', '京都值得游览。', 'CET4'),
  ('warm', '/wɒ:m/', 'a. 暖和的, 暖的, 温暖的, 热烈的, 兴奋的, 激烈的, 多情的, 色情的 vt. 使温暖, 弄热, 使兴奋, 使充满仇恨 vi. 变暖和, 变温暖, 取暖, 激动, 同情, 爱好 n. 暖, 保暖物', 'adj', 'You''re starting to warm up now.', '现在你开始热起来了。', 'CET4'),
  ('egg', '/eg/', 'n. 蛋, 卵 vt. 挑唆, 煽动, 调蛋黄', 'n', 'It''s about the size of an egg.', '它的大小就像鸡蛋。', 'CET4'),
  ('anybody', '/''enibɒdi/', 'pron. 任何人 n. 重要人物', 'pron', 'There wasn''t anybody in the house.', '没有人在家。', 'CET4'),
  ('gift', '/gift/', 'n. 礼物, 赠予, 天才 vt. 赋予', 'n', 'I cannot accept your gift.', '我不能接受你的礼物。', 'CET4'),
  ('coffee', '/''kɒfi/', 'n. 咖啡, 咖啡色 [医] 咖啡, 咖啡豆', 'n', 'Generally speaking, Americans are very fond of coffee.', '美国人一般都很喜欢喝咖啡。', 'CET4'),
  ('afraid', '/ә''freid/', 'a. 害怕的, 恐怕的, 遗憾的', 'adj', 'I''m afraid to fall.', '我怕摔倒。', 'CET4'),
  ('quarter', '/''kwɒ:tә/', 'n. 四分之一, 一刻钟, 季度, 地区 vt. 四等分, 肢解 vi. 驻扎, 住宿', 'n', 'Corporate earnings in the first quarter improved sharply.', '企业第一季度收益大幅增长。', 'CET4'),
  ('twice', '/twais/', 'adv. 两次, 两倍', 'adv', 'Smokers take twice as many days off sick as non-smokers.', '吸烟的人请病假的日数比不吸烟的人多两倍。', 'CET4'),
  ('blow', '/blәu/', 'n. 吹, 打击, 殴打, 花开 v. 吹, 风吹, 吹响, 开花', 'n', 'Make a wish and blow out the candles.', '许个愿，然后吹熄蜡烛吧。', 'CET4'),
  ('cook', '/kuk/', 'n. 厨子, 厨师 vt. 烹调, 煮饭, 加热 vi. 在煮着', 'n', 'Do you know how to cook meat?', '你知道怎么煮肉吗?', 'CET4'),
  ('shoe', '/ʃu:/', 'n. 鞋, 靴, 外胎 vt. 给...穿鞋, 为马钉蹄铁', 'n', 'Only a shoe knows about a hole in a sock.', '只有鞋子知道袜子的洞。', 'CET4'),
