  ('pen', '/pen/', 'n. 钢笔, 笔, 笔调, 笔杆子, 作家, 围栏, 栅栏, 禽畜 vt. 写, 关入栏中, 囚禁 vi. 动笔, 写作', 'n', 'Do you have a pen on you?', '你身上有铅笔吗？', 'CET4'),
  ('hurry', '/''hʌri/', 'n. 匆忙, 急忙, 急促 vt. 急派, 催促 vi. 匆忙, 赶快', 'n', 'You didn''t need to hurry.', '你不需要著急。', 'CET4'),
  ('skirt', '/skә:t/', 'n. 裙子, 下摆, 边缘, 郊区 vt. 位于...边缘, 绕过, 回避 vi. 位于边缘', 'n', 'I''m looking for a warm, woolen skirt.', '我想找一件温暖的羊毛裙。', 'CET4'),
  ('forty', '/''fɒ:ti/', 'num. 四十, 四十个', 'num', 'This book contains forty photographs.', '这本书里面有四十张照片。', 'CET4'),
  ('noon', '/nu:n/', 'n. 正午, 中午, 全盛期', 'n', 'You have to get this work finished by noon.', '你必须在中午以前完成这个工作。', 'CET4'),
  ('doll', '/dɒl/', 'n. 洋娃娃, 无头脑的美丽女人', 'n', 'Mary gave me an American doll.', '玛丽给了我一个美国娃娃。', 'CET4'),
  ('hers', '/hә:z/', 'pron. 她的', 'pron', 'Nancy ran across an old friend of hers yesterday.', 'Nancy昨天巧遇了她的一个老朋友。', 'CET4'),
  ('gym', '/dʒim/', 'n. +体育馆, 体育训练, 体育课, 体操', 'n', 'We played basketball in the gym.', '我们在体育馆打篮球。', 'CET4'),
  ('silk', '/silk/', 'n. 丝, 绸, 绸锻类, 丝织品 a. 丝的, 丝织的', 'n', 'I sewed the dress with silk thread.', '我用丝线缝了这条裙子。', 'CET4'),
  ('ours', '/''auәz/', 'pron. 我们的', 'pron', 'Your team is stronger than ours.', '你们的队伍比我们的强。', 'CET4'),
  ('seventh', '/''sevnθ/', 'num. 第七, 七分之一', 'num', 'India is the seventh largest country in the world.', '印度是世界第七大的国家。', 'CET4'),
  ('aunt', '/ɑ:nt/', 'n. 阿姨, 姨妈, 舅妈, 姑妈, 伯母', 'n', 'What does your aunt do?', '你姑姑是做什么的？', 'CET4'),
  ('sheep', '/ʃi:p/', 'n. 羊, 胆小者', 'n', 'Cheese is a solid food made from the milk of cows, goats, sheep, and other mammals.', '奶酪是由母牛、山羊、绵羊或其它哺乳动物的奶加工制成的固体食物。', 'CET4'),
  ('exam', '/ig''zæm/', 'n. 考试, 测验', 'n', 'If you study earnestly, you can expect to pass the exam.', '如果你认真学习，就有希望通过考试。', 'CET4');;

INSERT INTO `word_dictionary` (`word`, `phonetic`, `translation`, `pos`, `example`, `example_translation`, `level`) VALUES
  ('pork', '/pɒ:k/', 'n. 猪肉 [医] 猪肉', 'n', 'That''s why ostrich meat costs more than twice as much as beef and pork.', '这就是驼鸟肉比牛肉和猪肉贵两倍多的原因了。', 'CET4'),
  ('eleven', '/i''levn/', 'num. 十一, 十一个', 'num', 'It is already eleven.', '已经是11点了。', 'CET4'),
  ('grandchild', '/''^rændtʃaild/', 'n. 孙, 外孙女, 外孙, 孙女, 孙子', 'n', 'Maybe my grandchild will be the first person to set foot on Mars.', '可能我的孙子会是登陆火星的第一人。', 'CET4'),
  ('pencil', '/''pensl/', 'n. 铅笔, 色笔, 眉笔, 画笔, 光线束 vt. 用铅笔写或涂, 草拟', 'n', 'You dropped your pencil.', '你把你的铅笔弄掉了。', 'CET4'),
  ('eighth', '/eitθ/', 'num. 第八, 八分之一', 'num', 'Neptune is the eighth planet of the solar system.', '海王星是太阳系第八个行星。', 'CET4'),
  ('swimming', '/''swimiŋ/', 'n. 游泳, 眩晕', 'n', 'Have you ever seen him swimming?', '你曾看过他游泳吗？', 'CET4'),
  ('pioneer', '/.paiә''niә/', 'n. 先锋, 拓荒者, 创始人 vt. 提倡, 开辟, 开创, 倡导 vi. 作先驱, 开路 a. 最早的, 开拓的, 先驱的, 有开拓者特点的', 'n', NULL, NULL, 'CET4'),
  ('kilometre', '/''kilәjmi:tә(r)/', 'n. 公里, 千米', 'n', NULL, NULL, 'CET4'),
  ('spare', '/spєә/', 'n. 剩余, 备用品, 备件, 备用零件, 备用轮胎 a. 多余的, 备用的, 空闲的, 节约的, 瘦的 vi. 节约, 省掉, 宽恕 vt. 节约, 省用, 剩下, 饶恕, 赦免', 'n', 'We have three spare rooms, none of which can be used.', '虽然有三间空屋，但哪间都用不了。', 'CET4'),
  ('banana', '/bә''nɑ:nә/', 'n. 香蕉', 'n', 'Have you ever eaten a banana pie?', '你吃过香蕉派吗？', 'CET4'),
  ('palace', '/''pælis/', 'n. 宫, 宫殿, 华丽大厦', 'n', 'The palace was heavily guarded.', '皇宫警衞森严。', 'CET4'),
  ('grandparent', '/''grændperәnt/', 'n. 祖父母', 'n', NULL, NULL, 'CET4'),
  ('supermarket', '/''sju:pәmɑ:kit/', 'n. 超级市场 [经] 超级市场, 自助售货商店', 'n', 'The supermarket opens at ten o''clock.', '超级市场在十点开门。', 'CET4'),
  ('policeman', '/pә''li:smәn/', 'n. 警察 [化] 淀帚', 'n', 'A policeman ran past.', '一名警官跑过。', 'CET4'),
  ('homework', '/''hәumwә:k/', 'n. 家庭作业, 家里做的工作 [经] 家庭作业', 'n', 'Did you do your homework by yourself?', '你自己做回家作业的吗?', 'CET4'),
  ('pence', '/pens/', 'pl. (非正式)copper便士, (美)分, 分币', 'pl', 'Six pence per second, Bob reminds her.', '每秒六便士 鲍勃提醒她。', 'CET4'),
  ('sunny', '/''sʌni/', 'a. 阳光充足的, 乐观的, 快乐的, 像太阳的', 'adj', 'I have to do laundry while it''s still sunny.', '趁还有太阳的时候，我该洗衣服。', 'CET4'),
  ('shorts', '/ʃɔ:ts/', 'n. 短裤, (美)男人的短衬裤 [经] 空头户, 空头, 短期债券', 'n', 'Khaki shorts with cargo pockets do not make you an adventurer.', '单有卡其裤，还成不了冒险家。', 'CET4'),
  ('zero', '/''ziәrәu/', 'n. 零, 零点, 零度, 无, 乌有, 最低点 a. 零的, 没有的 vt. 调零, 对(炮火等)作协调校正 [计] 零', 'n', 'The thermometer went down below zero.', '温度计上的温度跌到了零度以下。', 'CET4'),
  ('twentieth', '/''twentiiθ/', 'num. 第二十, 二十分之一', 'num', 'One out of 455 women doesn''t realize she''s pregnant until the twentieth week of pregnancy.', '455名妇女中会有一名直到怀孕第二十周前没有意识到自己怀孕。', 'CET4'),
  ('till', '/til/', 'prep. 直到, 在...以前, 迄 conj. 直到...为止 vt. 耕种 n. 放钱的抽屉, 备用现金, 冰碛', 'prep', 'If you think education is expensive, wait till you see what ignorance costs you.', '如果你认为教育是昂贵的, 那么你等著看无知让你付出的代价。', 'CET4'),
  ('boring', '/''bɒ:riŋ/', 'a. 烦人的, 无聊的, 无趣的 [机] 成孔期, 搪孔', 'adj', 'Sometimes I have to read boring novels.', '有时候，我不得不读一些无聊的小说。', 'CET4'),
  ('website', NULL, 'n. 网站（全球资讯网的主机站）', 'n', 'I really like the concept of this website.', '我觉得这个网站的概念非常好。', 'CET4'),
  ('autumn', '/''ɒ:tәm/', 'n. 秋天, 成熟期', 'n', 'The rain made the autumn day dismal.', '雨让秋天的日子阴沉沉的。', 'CET4'),
  ('pupil', '/''pju:pl/', 'n. 学生, 门生, 未成年人, 瞳孔 [医] 瞳孔', 'n', 'For example, if a chain-smoking teacher cautions a pupil for smoking, that warning is self-contradictory.', '举例说，如果一个老师警告学生不要吸烟，但自己却每天吸个不停，那么这个警告就是自相矛盾的了。', 'CET4'),
  ('ninth', '/nainθ/', 'num. 第九, 九分之一', 'num', NULL, NULL, 'CET4'),
  ('stamp', '/stæmp/', 'n. 印, 邮票, 打印器, 戳子, 图章, 印花税票, 标志, 特征, 类型, 跺脚 vt. 盖章于, 顿足, 贴上邮票, 铭刻, 捣碎, 扑灭 vi. 捣碎, 跺脚', 'n', 'Put this stamp on the postcard and drop it in the mailbox.', '把这张邮票贴在明信片上，然后投到邮箱里。', 'CET4'),
  ('taxi', '/''tæksi/', 'n. 出租车 vi. 乘出租车 vt. 用出租车送', 'n', 'I went to the airport by taxi.', '我搭计程车去的机场。', 'CET4'),
  ('australian', '/ɒ''streiljәn/', 'n. 澳大利亚人 a. 澳大利亚的, 澳洲的, 澳洲人的', 'n', NULL, NULL, 'CET4'),
  ('countryside', '/''kʌntrisaid/', 'n. 乡下地方, 乡下居民', 'n', 'The countryside has many trees.', '乡间有很多树。', 'CET4'),
  ('sixteen', '/''siks''ti:n/', 'num. 十六, 十六个', 'num', 'I''ll be sixteen in September.', '我九月份就十六岁了。', 'CET4'),
  ('underground', '/''ʌndәgraund/', 'n. 地下, 地铁, 地道, 秘密活动 a. 地下的, 秘密的 adv. 在地下, 秘密地', 'n', 'London is such a large city that visitors must use buses and the underground railway to get about.', '伦敦是个大城市，游客必须乘公交或地铁才能出行。', 'CET4'),
  ('theirs', '/ðєәz/', 'pron. 他们的', 'pron', 'Your team is very good, but theirs is the best.', '你们是个非常好的团队，但他们的是最好的。', 'CET4'),
  ('hometown', '/hәum''taun/', 'n. 故乡, 家乡', 'n', 'Tom went back to his hometown.', '汤姆回乡下了。', 'CET4'),
  ('polite', '/pә''lait/', 'a. 有礼貌的, 文雅的, 客气的, 有教养的', 'adj', 'You should try to be more polite.', '你应该试著更有礼貌。', 'CET4'),
  ('fourteen', '/''fɒ:''ti:n/', 'num. 十四, 十四个', 'num', 'I lost my father to a subarachnoid haemorrhage when I was fourteen.', '我十四岁的时候，父亲死于蛛网膜下出血。', 'CET4'),
  ('supper', '/''sʌpә/', 'n. 晚餐', 'n', 'You should apologize to Dad for not coming home in time for supper.', '你应该为你没有及时回家吃晚餐向你父亲道歉。', 'CET4'),
  ('goodbye', '/gud''bai/', 'interj. 再见', 'interj', 'I''m afraid I must say goodbye.', '恐怕我必须说再见了。', 'CET4'),
  ('thirteen', '/''θә:''ti:n/', 'num. 十三, 十三个', 'num', 'When she was thirteen, she ran away from home.', '她十三岁的时候离家出走了。', 'CET4'),
  ('umbrella', '/ʌm''brelә/', 'n. 伞, 雨伞, 保护伞 a. 伞的, 包罗万象的 vt. 用伞遮掩', 'n', 'You had better take an umbrella with you.', '你最好随身带把伞。', 'CET4'),
  ('motorcycle', '/''mәutәsaikl/', 'n. 摩托车 [机] 机动车, 机踏车, 摩托车', 'n', 'I don''t know how much this motorcycle is.', '我不知道这辆摩托车多少钱。', 'CET4'),
  ('passport', '/''pæspɒ:t/', 'n. 护照, 手段, 通行证 [法] 通行证, 护照', 'n', 'When you''re beginning to look like the photo in your passport, you should go on a holiday.', '当我们开始像自己护照上的照片时，我们该去度假了。', 'CET4'),
  ('zoo', '/zu:/', 'n. 动物园', 'n', 'I went to the zoo yesterday.', '我昨天去了动物园。', 'CET4'),
  ('hobby', '/''hɒbi/', 'n. 嗜好, 癖好, 爱好', 'n', 'Aoi''s hobby is dancing.', '葵的嗜好是跳舞。', 'CET4'),
  ('chant', '/tʃænt. tʃɑ:nt/', 'n. 圣歌, 赞美诗 v. 吟唱, 诵扬', 'n', NULL, NULL, 'CET4'),
  ('postcard', '/''pәustkɑ:d/', 'n. 明信片', 'n', 'Prepare five postcard sized pieces of cardboard.', '准备五张明信片大小的硬纸板。', 'CET4'),
  ('pity', '/''piti/', 'n. 遗憾, 同情, 怜悯, 憾事, 可惜 vt. 同情, 怜悯 vi. 觉得可怜, 有同情心', 'n', 'It''s a pity when somebody dies.', '有人死了的时候真是遗憾。', 'CET4'),
  ('pancake', '/''pænkeik/', 'n. 薄烤饼, 薄煎饼, 烙饼', 'n', NULL, NULL, 'CET4'),
  ('madame', '/''mædәm/', 'n. 夫人, 小姐, 太太, 女士, 主妇, (非正式)喜欢差使/指使别人的女子, 鸨母', 'n', NULL, NULL, 'CET4'),
  ('tenth', '/tenθ/', 'num. 第十, 十分之一', 'num', 'School begins on April the tenth.', '学校在四月十日开学。', 'CET4'),
  ('pardon', '/''pɑ:dn/', 'n. 原谅, 赦免 vt. 宽恕, 原谅', 'n', 'I beg your pardon?', '不好意思，能请您重复一遍吗？', 'CET4'),
  ('yourselves', '/jɔ:''selvz,jjә-,jә-/', 'pron. 你们自己', 'pron', 'You people can''t help yourselves.', '你们这些人办不成了。', 'CET4'),
  ('noodle', '/''nu:dl/', 'n. 面条, 笨蛋', 'n', 'There''s a fly in the noodle broth.', '面汤里有个苍蝇。', 'CET4'),
  ('china', '/''tʃainә/', 'n. 中国, 瓷器 a. 中国的', 'n', NULL, NULL, 'CET4'),
  ('cinema', '/''sinәmә/', 'n. 电影院, 电影', 'n', 'Smoking is not permitted in the cinema.', '电影院内不准吸烟。', 'CET4'),
  ('ninety', '/''nainti/', 'num. 九十, 九十个', 'num', 'My grandfather lived to be ninety.', '我的祖父活到了九十岁。', 'CET4'),
  ('railway', '/''reilwei/', 'n. 铁路, 轨道 [经] 铁路', 'n', 'London is such a large city that visitors must use buses and the underground railway to get about.', '伦敦是个大城市，游客必须乘公交或地铁才能出行。', 'CET4'),
  ('dictionary', '/''dikʃәnәri/', 'n. 字典, 词典 [计] 词典', 'n', 'In a dictionary like this one there should be at least two sentences with "fridge".', '这样的字典最少也应该有两句「冰箱」的例句吧。', 'CET4'),
  ('clone', '/klәun/', 'n. 无性系 [计] 代用件', 'n', NULL, NULL, 'CET4'),
  ('grandma', '/''grændmɑ:/', 'n. 奶奶, 外婆', 'n', 'We''re worried about Grandma and Grandpa.', '我们担心着爷爷和奶奶。', 'CET4'),
  ('cloudy', '/''klaudi/', 'a. 多云的, 有愁容的, 云的, 浑浊的 [建] (混)浊的', 'adj', 'It was cloudy that night.', '那晚多云。', 'CET4'),
  ('thirsty', '/''θә:sti/', 'a. 口渴的, 渴望的, 干燥的', 'adj', 'I''m always thirsty.', '我总觉得渴。', 'CET4'),
  ('behaviour', '/bi''heivjә/', 'n. 行为, 举止 [计] 特性, 性能, 特点, 行为, 动作, 状态', 'n', 'I can''t take his behaviour.', '我无法容忍他的行为。', 'CET4'),
  ('mend', '/mend/', 'n. 改进, 修补, 好转 vt. 修改, 改进, 加快, 修理 vi. 好转, 改善', 'n', 'I want to mend this watch.', '我想修这块手表。', 'CET4'),
  ('watermelon', '/''wɒtә.melәn/', 'n. 西瓜', 'n', 'I''ve never seen such a giant watermelon!', '我从没见过那么大的西瓜！', 'CET4'),
  ('kilo', '/''kilәu/', 'n. 千 [计] 千', 'n', 'How much is the kilo of bananas?', '一公斤香蕉多少钱?', 'CET4'),
  ('lemonade', '/.lemә''neid/', 'n. 柠檬水 [医] 柠檬水', 'n', NULL, NULL, 'CET4'),
  ('handbag', '/''hændbæg/', 'n. 手提包', 'n', 'She had her handbag stolen.', '她的手提包被偷了。', 'CET4'),
  ('coke', '/kәuk/', 'n. 可口可乐, 焦炭 v. (使)成焦炭', 'n', 'Go and buy three bottles of coke.', '去买三瓶可乐。', 'CET4'),
  ('crayon', '/''kreiәn/', 'n. 蜡笔, 蜡笔画 vt. 以蜡笔作画', 'n', NULL, NULL, 'CET4'),
  ('twelfth', '/twelfθ/', 'num. 第十二, 十二分之一', 'num', 'The old church on the hill dates back to the twelfth century.', '山上的老教堂的历史可以追溯到12世纪。', 'CET4'),
  ('blackboard', '/''blækbɒ:d/', 'n. 黑板', 'n', 'Compare your sentence with the one on the blackboard.', '比较一下你写的句子和黑板上的句子。', 'CET4'),
  ('cooker', '/''kukә/', 'n. 炊事用具, 炉灶, 锅, 炊具, 烹饪用水果, 窜改者, 伪造者 [化] 蒸锅', 'n', NULL, NULL, 'CET4'),
  ('toothbrush', '/''tu:θbrʌʃ/', 'n. 牙刷', 'n', 'That''s my toothbrush.', '这把是我的牙刷。', 'CET4'),
  ('stairs', NULL, 'n. 楼梯', 'n', 'Another step, and you would have fallen down the stairs.', '再走一步的话，你就已经跌下楼梯了。', 'CET4'),
  ('toothpaste', '/''tu:θpeist/', 'n. 牙膏 [化] 牙膏', 'n', 'Where can I find toothpaste?', '在哪儿我能找到牙膏？', 'CET4'),
  ('dumpling', '/''dʌmpliŋ/', 'n. 面团布丁, 团子', 'n', 'In Chinese, ''dumpling'' and ''first exchange'' are homophones, so they have a rich cultural association.', '在中文里面，饺子和“交子”谐音，因而具有丰富的文化涵义。', 'CET4'),
  ('grandpa', '/''^rænpɑ:, ''^rændpɑ:/', '爷爷, 老太爷, 外公', NULL, 'Grandpa bought it for me!', '爷爷买给我的！', 'CET4'),
  ('raincoat', '/''reinkәut/', 'n. 雨衣', 'n', 'You had better put on a raincoat.', '您最好穿一件雨衣。', 'CET4'),
  ('giraffe', '/dʒi''rɑ:f/', 'n. 长颈鹿, 鹿豹座', 'n', 'What sound does a giraffe make?', '长颈鹿是怎么叫的？', 'CET4'),
  ('housework', '/''hauswә:k/', 'n. 家事, 家务', 'n', 'It is time not only to equalize men''s and women''s wages, but also to equalize responsibility for housework.', '现在不止要男女薪金平等，而且还要平均分配家务。', 'CET4'),
  ('eraser', '/i''reisә/', 'n. 擦子', 'n', 'Rub out these words with your eraser.', '用你的橡皮把这些字擦掉。', 'CET4'),
  ('chopsticks', '/''tʃɒpstiks/', 'n. 筷子', 'n', 'Lucy cannot use chopsticks.', '露西不会用筷子。', 'CET4'),
  ('bye', '/bai/', 'interj. 再会, 回头见 [计] 结束命令', 'interj', 'He departed without so much as saying good bye.', '他连再见也不说就走了。', 'CET4'),
  ('granny', '/''^ræni/', 'n. 奶奶, 老奶奶, 老婆婆, 外婆, 婆婆妈妈的人, 唠叨挑剔的人, 接生婆', 'n', NULL, NULL, 'CET4'),
  ('august', '/ɒ:''gʌst. ''ɒ:gәst/', 'n. 八月 a. 威严的, 令人敬畏的', 'n', 'Jack was born on August tenth.', '杰克在八月十日出生。', 'CET4'),
