  ('cab', '/kæb/', 'n. 出租车, 出租汽车, 出租马车 vi. 乘出租马车(或汽车)', 'n', 'I left my umbrella in the cab.', '我把我的伞忘在计程车上了。', 'CET4'),
  ('f', '/ef/', '[计] 故障, 假, 法拉, 字段, 标记, 特征, 分数, 频率, 函数, 功能', NULL, NULL, NULL, 'CET4'),
  ('workplace', NULL, 'n. 工作场所, 工厂, 车间', 'n', 'Wienczysława is the most beautiful brunette in the workplace.', 'Wienczysława是这个工作场所里最美丽的黑发女人。', 'CET4'),
  ('switzerland', '/''switsәlәnd/', 'n. 瑞士', 'n', NULL, NULL, 'CET4'),
  ('alley', '/''æli/', 'n. 小路, 巷', 'n', 'This is a dead-end alley.', '这是个死胡同。', 'CET4'),
  ('mentally', '/''mentli/', 'adv. 心理上, 精神上, 智力上 [法] 精神上, 智力上', 'adv', 'You must be mentally exhausted.', '你肯定脑子糊掉了。', 'CET4'),
  ('surrounding', '/sә''raundiŋ/', 'n. 环境 a. 周围的', 'n', 'The surrounding area was very quiet.', '周围的地区非常安静。', 'CET4'),
  ('disabled', '/dis''eibld/', 'a. 残废的, 有缺陷的, 失效的 [计] 失效的', 'adj', 'A sprained ankle disabled him from walking for a month.', '他把足踝扭伤了，整整一个月不能走路。', 'CET4'),
  ('trainer', '/''treinә/', 'n. 训练员, 驯马师 [电] 列车器', 'n', 'The dolphin and trainer communicated much better than we expected.', '海豚和驯养员交流得比我们所期望的好得多。', 'CET4'),
  ('belgium', '/''beldʒәm/', 'n. 比利时', 'n', NULL, NULL, 'CET4'),
  ('disappointment', '/.disә''pɒintmәnt/', 'n. 失望', 'n', 'The new teacher was a disappointment to the class.', '新老师辜负了这个班学生的期望。', 'CET4'),
  ('mineral', '/''minәrәl/', 'n. 矿物, 无机物, 苏打水 a. 矿物的, 似矿物的', 'n', 'That country is rich in mineral resources.', '那个国家拥有丰富的矿物资源。', 'CET4'),
  ('happily', '/''hæpili/', 'adv. 幸福地, 快乐地, 幸好', 'adv', 'Nancy smiled happily.', '南希高兴地微笑了。', 'CET4'),
  ('tourism', '/''tuәrizm/', 'n. 观光业, 游览 [经] 旅游业', 'n', 'Tourism generated many new jobs.', '旅游业创造了许多新的工作职位。', 'CET4'),
  ('suite', '/swi:t/', 'n. 随员, 套房, (一)组, (一)套, 组曲, 继之而来的事 [电] 程序组', 'n', NULL, NULL, 'CET4'),
  ('crowded', '/''kraudid/', 'a. 拥挤的, 塞满的', 'adj', 'We were crowded into the small room.', '我们挤进了那间小房间里。', 'CET4'),
  ('graduation', '/.grædʒu''eiʃәn/', 'n. 毕业, 得学位, 分划, 刻度, 分等级 [医] 刻度, 分度, 毕业', 'n', 'The graduation from elementary school to middle school is regarded by some as the first step towards adulthood.', '有些人认为从小学升到中学是踏入成年的第一步。', 'CET4'),
  ('ha', '/hɑ:/', 'interj. 嘿, 哈, 哈哈', 'interj', 'Ha - this work''s finished! Let''s move on to the next stage!', '这个工作完成了!我们进入下一步吧!', 'CET4');;

INSERT INTO `word_dictionary` (`word`, `phonetic`, `translation`, `pos`, `example`, `example_translation`, `level`) VALUES
  ('disturbing', '/dis''tә:biŋ/', 'a. 引起烦恼的, 令人不安的', 'adj', 'I hope I''m not disturbing you.', '我希望没打扰到你吧？', 'CET4'),
  ('bride', '/braid/', 'n. 新娘', 'n', 'Food and drink were served in such profusion at the wedding that the bride and groom began to wonder if they should not have invited more guests.', '婚礼上饮料和食物那么丰富以至于那对年轻的新人开始怀疑他们本不该邀请更多的客人。', 'CET4'),
  ('biography', '/bai''ɒgrәfi/', 'n. 传记', 'n', NULL, NULL, 'CET4'),
  ('nationwide', '/''neiʃәnwaid/', 'a. 全国性的 [法] 全国的, 全国范围的', 'adj', 'It is a prevalent belief, according to a nationwide poll in the United States, that Muslims are linked with terrorism.', '根据美国国民的一个投票，人们普遍认为穆斯林人和恐怖主义有关。', 'CET4'),
  ('smoking', '/''smәukiŋ/', 'n. 抽烟, 冒烟 [医] 烟熏; 吸烟', 'n', 'You should make an effort to stop smoking.', '你应该努力去戒烟。', 'CET4'),
  ('challenging', '/''tʃælindʒiŋ/', 'a. 挑战的, 引起争论的', 'adj', 'We express our gratitude for Mr Smith''s outstanding, challenging speech.', '我们对史密斯先生杰出的，给人启发的讲话表示感激。', 'CET4'),
  ('cowboy', '/''kaubɒi/', 'n. 牛仔, 牛郎, 牧童', 'n', NULL, NULL, 'CET4'),
  ('chat', '/tʃæt/', 'n. 闲谈 vi. 闲谈, 聊天', 'n', 'Nancy is having a chat with her friends.', 'Nancy正在和她的朋友们聊天。', 'CET4'),
  ('adaptation', '/.ædæp''teiʃәn/', 'n. 适应, 改编, 改编本 [医] 适应[作用]', 'n', NULL, NULL, 'CET4'),
  ('nursing', '/''nә:siŋ/', 'n. 看护, 养育 [医] 护理[法], 喂乳[法]', 'n', 'There is a bus stop near a nursing home in Cologne. No bus ever stops there. It''s created for the purpose of finding mental patients on the run more easily.', '在科隆一家疗养院的附近有一个公交车站。这一站没有任何公交车停靠。它是为更加容易地寻找逃跑的精神病患者而设立的。', 'CET4'),
  ('dusty', '/''dʌsti/', 'a. 灰尘多的, 无聊的, 含糊的, 粉末状的', 'adj', NULL, NULL, 'CET4'),
  ('breakthrough', '/''breikθru:/', 'n. 突破 [经] 突破, 新发现, 新进展', 'n', NULL, NULL, 'CET4'),
  ('dinosaur', '/''dainәsɒ:/', 'n. 恐龙', 'n', 'Coming face to face with a dinosaur was a funny experience.', '和一只恐龙面对面是一段有趣的经历。', 'CET4'),
  ('choir', '/''kwaiә/', 'n. 唱诗班, 唱诗班的席位 v. 合唱', 'n', NULL, NULL, 'CET4'),
  ('vanilla', '/vә''nilә/', 'n. 香草, 香子兰', 'n', 'If and only if the ice-cream is vanilla flavour will Xiao Wang eat it.', '当且仅当冰淇淋是香草口味，小王会吃这个冰淇淋。', 'CET4'),
  ('wounded', NULL, 'a. 受伤的 [法] 受伤者; 受伤的, 受了损害的', 'adj', 'Many soldiers were wounded in the battle.', '很多士兵在战斗中受了伤。', 'CET4'),
  ('grill', '/gril/', 'n. 烤架, 铁格子, 烤肉 v. 烧, 烤, 严加盘问, 给...装栅栏', 'n', NULL, NULL, 'CET4'),
  ('tokyo', '/''tәukjәu/', 'n. 东京 [经] 东京', 'n', NULL, NULL, 'CET4'),
  ('settler', '/''setlә/', 'n. 移民者, 解决者, 结算员 [化] 沉淀池; 沉降器; 澄清槽', 'n', NULL, NULL, 'CET4'),
  ('firefighter', '/ˈfaɪəfaɪtə(r)/', 'n. <美>消防队员', 'n', 'My dream is to become a firefighter.', '我的梦想是成为一名消防员。', 'CET4'),
  ('modem', '/''mәudem/', 'n. 调制解调器 [计] 调制解调器', 'n', NULL, NULL, 'CET4'),
  ('fried', '/fraid/', 'a. 油炸的', 'adj', 'I ate fried rice and drank some beer.', '我吃了炒饭，也喝了啤酒。', 'CET4'),
  ('boxing', '/''bɒksiŋ/', 'n. 拳击 [医] 围模(牙科)', 'n', 'Boxing is not always a rough sport.', '拳击并不总是一种粗暴的运动。', 'CET4'),
  ('loudly', '/''laudli/', 'adv. 高声地, 大声地, 吵闹地', 'adv', 'The telephone on my desk rang persistently and loudly.', '我桌上的电话一直大声响铃。', 'CET4'),
  ('litre', '/li:tә(r)/', 'n. 升, 公升 [计] 升', 'n', NULL, NULL, 'CET4'),
  ('facial', '/''feiʃәl/', 'n. 美颜, 脸部按摩 a. 脸的, 表面的, 脸部用的', 'n', 'I want to pluck your facial hair.', '我想拔你的胡须。', 'CET4'),
  ('courtyard', '/''kɒ:tjɑ:d/', 'n. 庭院, 天井', 'n', 'In Beijing, hutongs are alleys formed by lines of siheyuans, the traditional courtyard residences.', '在北京，胡同是由四合院的传统居所排形成。', 'CET4'),
  ('bored', NULL, 'a. 无聊的；烦人的；无趣的', 'adj', 'You look bored.', '你看起来很无聊。', 'CET4'),
  ('saying', '/''seiiŋ/', 'n. 叙述, 话, 说, 言论', 'n', 'I''m just saying!', '我只是说说而已！', 'CET4'),
  ('easter', '/''i:stә/', 'n. 复活节', 'n', NULL, NULL, 'CET4'),
  ('accountant', '/ә''kauntәnt/', 'n. 会计人员, 会计师 [经] 会计师, 会计人员', 'n', 'Allan was lucky and passed the tax accountant examination.', '艾伦很幸运地考过了税务师考试。', 'CET4'),
  ('fairness', '/''fєәnis/', 'n. 晴朗, 光明正大, 美丽 [经] 公正, 适当', 'n', 'In all fairness, he did do his best.', '说句实话，他真的尽力了。', 'CET4'),
  ('coral', '/''kɒrәl/', 'n. 珊瑚, 珊瑚色 [化] 珊瑚', 'n', 'The coral reef is the region''s prime attraction.', '珊瑚礁是这个地区的主要景点。', 'CET4'),
  ('unbelievable', '/.ʌnbi''li:vәbl/', 'a. 难以置信的', 'adj', NULL, NULL, 'CET4'),
  ('villager', '/''vilidʒә/', 'n. 村民', 'n', NULL, NULL, 'CET4'),
  ('kindergarten', '/''kindә.gɑ:tn/', 'n. 幼稚园', 'n', 'The teachers are playing games with students in the kindergarten.', '幼儿园里，老师正在带领小朋友们嘻戏。', 'CET4'),
  ('pyramid', '/''pirәmid/', 'n. 角锥, 金字塔 v. (使)成金字塔状, (使)渐增, (使)上涨', 'n', 'There''s a pyramid in Mexico bigger than any of those in Egypt.', '在墨西哥有一座金字塔比在埃及的任何一座都大。', 'CET4'),
  ('decoration', '/.dekә''reiʃәn/', 'n. 装饰, 装饰品', 'n', 'This house is nearby, it has two bedrooms and a living room, and the decoration isn''t bad; it''s 1500 a month.', '这房子在附近，两室一厅，装修也不错，一个月1500。', 'CET4'),
  ('freeway', '/''fri:wei/', 'n. 高速公路', 'n', NULL, NULL, 'CET4'),
  ('bookstore', '/''bukstɒ:/', 'n. 书店', 'n', 'Every now and then he drops in at this bookstore on his way home from the office.', '有时从办公室回家的路上他会到这家书店看一看。', 'CET4'),
  ('encouragement', '/in''kʌridʒmәnt/', 'n. 鼓励, 激励, 奖励 [法] 怂恿, 煽动, 助长', 'n', 'Tom needs encouragement.', '汤姆需要鼓励。', 'CET4'),
  ('crossing', '/''krɒsiŋ/', 'n. 横越, 横渡, 交叉点, 渡口 [经] 划线', 'n', 'He overcame all sorts of hardship and setbacks to succeed in a solo crossing of Antarctica.', '他克服了种种困难和挫折，终于成功一个人越过了南极洲。', 'CET4'),
  ('awesome', '/''ɒ:sәm/', 'a. 引起敬畏的, 可怕的', 'adj', 'That''s awesome, right?', '很棒，不是吗？', 'CET4'),
  ('novelist', '/''nɒvәlist/', 'n. 小说家', 'n', 'I have a friend whose father is a famous novelist.', '我有一位朋友，他的父亲是著名小说家。', 'CET4'),
  ('freezing', '/''fri:ziŋ/', 'a. 冰冻的, 冷冻用的, 严寒的 [化] 冻结; 冻结作用; 凝固; 凝固作用', 'adj', 'The temperature has been below freezing for several days.', '零度以下的气温持续了好几天。', 'CET4'),
  ('flashlight', '/''flæʃlait/', 'n. 手电筒, 闪光信号灯', 'n', 'You won''t be able to see anything without a flashlight.', '没有手电筒的话，你啥都看不到。', 'CET4'),
  ('download', NULL, '[计] 卸载, 下栽', NULL, 'If you do not have this program, you can download it now.', '假如你没有这个程序，你现在就可以去下载。', 'CET4'),
  ('cuisine', '/kwi:''zi:n/', 'n. 烹调风格, 烹调法, 烹饪, 厨房', 'n', 'I want to eat French cuisine.', '我想吃法国菜。', 'CET4'),
  ('bureaucratic', '/bjuәrәu''krætik/', 'a. 官僚的 [经] 机僚化的', 'adj', NULL, NULL, 'CET4'),
  ('receipt', '/ri''si:t/', 'n. 收据, 收入, 收到 vt. 开...的收据', 'n', 'I''d like a receipt, please.', '麻烦我要一张收据。', 'CET4'),
  ('cleaner', '/''kli:nә/', 'n. 清洁工人, 清洁剂, 干洗商 [化] 滤清器; 除垢器; 洗净剂; 清洁剂', 'n', 'The air of Sydney is cleaner than that of Tokyo.', '悉尼的空气比东京的要干净。', 'CET4'),
  ('brochure', '/''brәuʃә/', 'n. 小册子, 小册', 'n', 'Could you send me a brochure?', '你能寄宣传册给我吗？', 'CET4'),
  ('delighted', '/di''laitid/', 'a. 高兴的, 快乐的', 'adj', 'You look very delighted.', '你看起来很高兴。', 'CET4'),
  ('workforce', NULL, 'n. 劳动力；工人总数, 职工总数', 'n', NULL, NULL, 'CET4'),
  ('overweight', '/''әuvә''weit/', 'n. 超过重量, 过重, 优势 a. 超过重量的, 超重的 vt. 使超重, 重于, 过于重视', 'n', 'BMI categories (underweight, overweight or obese) from general reading table are inappropriate for athletes, children, the elderly, and the infirm.', '总读数表的身高体重指数分类（体重过轻、超重或肥胖）不适用于运动员、儿童、老人和体弱者。', 'CET4'),
  ('smoker', '/''smәukә/', 'n. 吸烟者, 吸烟的人, 吸烟车厢, (美)(非正式)蒸汽火车头', 'n', 'My father is a heavy smoker.', '我爸爸吸烟很厉害。', 'CET4'),
  ('messy', '/''mesi/', 'a. 散乱的, 污秽的, 麻烦的', 'adj', NULL, NULL, 'CET4'),
  ('barbecue', '/''bɑ:bikju:/', 'n. 烤肉 vt. 烤肉, 烧烤', 'n', 'We''ll have a barbecue at the beach.', '我们要在海边烤肉。', 'CET4'),
  ('translator', '/træn''leitә/', 'n. 翻译者 [计] 翻译程序; 翻译器', 'n', 'Because I want to be a translator.', '因为我想成为翻译。', 'CET4'),
  ('paperwork', '/''peipәwә:k/', 'n. 文书工作', 'n', NULL, NULL, 'CET4'),
  ('adolescence', '/.ædәu''lesәns/', 'n. 青春期 [医] 青年期, 青春期', 'n', 'In adolescence, I hated life and was continually on the verge of suicide, from which, however, I was restrained by the desire to know more mathematics.', '在青春期，我厌倦生活，并持续陷入自杀的边缘。然而，在那期间，对数学知识的渴望，使我抑制住了那些负面情绪。', 'CET4'),
  ('sunglasses', NULL, 'n. 太阳镜, 墨镜, 太阳眼镜', 'n', 'I need a good pair of sunglasses.', '我需要一副好的太阳眼镜。', 'CET4'),
  ('gardening', '/''gɑ:dniŋ/', 'n. 园艺(学)', 'n', 'Gardening has been popular for some years.', '园艺在这几年很流行。', 'CET4'),
  ('printing', '/''printiŋ/', 'n. 印刷, 印刷术, 印花 [计] 打印; 印刷', 'n', 'Printing ink is in short supply.', '油墨快没了。', 'CET4'),
  ('franc', '/fræŋk/', 'n. 法郎', 'n', NULL, NULL, 'CET4'),
  ('chick', '/tʃik/', 'n. 小鸡, 小鸟, 竹帘', 'n', NULL, NULL, 'CET4'),
  ('puzzled', NULL, 'a. 困惑的, 迷惑的', 'adj', 'I was puzzled about what to do next.', '我对以后做什么很迷茫。', 'CET4'),
  ('pub', '/pʌb/', 'n. 酒馆, 客栈', 'n', 'There''s a pub just around the corner.', '在转角有一家酒吧。', 'CET4'),
  ('autonomous', '/ɒ:''tɒnәmәs/', 'a. 自治的 [医] 自主的', 'adj', NULL, NULL, 'CET4'),
  ('founding', '/''faundiŋ/', '[计] 铸造', NULL, 'The twelve stars on the flag of the European Union do not symbolize the twelve founding members of the union. They symbolize the Twelve Apostles.', '欧盟盟旗的十二颗星代表的不是创立联盟的十二个会员国，而是十二门徒。', 'CET4'),
  ('preview', '/''pri:vju:/', 'n. 事先查看, 预览 vt. 事先查看, 预演 [计] 预览', 'n', NULL, NULL, 'CET4'),
  ('harmless', '/''hɑ:mlis/', 'a. 无害处的, 未受损害的, 无辜的, 无恶意的 [法] 无害的, 无恶意的, 无损害的', 'adj', 'Liberty consists of being able to make everything as harmless as possible.', '自由旨在能够做所有不伤害其他人的事。', 'CET4'),
  ('rewrite', '/ri:''rait/', 'vt. 重写, 改写, 改写新闻, 书面答复 vi. 修改旧作 n. 改写的作品 [计] 重写', 'vt', 'You should rewrite this sentence.', '你应该重写这句话。', 'CET4'),
  ('outing', '/''autiŋ/', 'n. 郊游, 远足 a. 远足适用的', 'n', NULL, NULL, 'CET4'),
  ('unsuccessful', '/.ʌnsәk''sesful/', 'a. 不成功的', 'adj', NULL, NULL, 'CET4'),
  ('alcoholic', '/.ælkә''hɒlik/', 'n. 酒鬼, 酒精中毒者 a. 酒精的', 'n', 'My mother was an alcoholic.', '我母亲是个酒鬼。', 'CET4'),
  ('opener', '/''әupәnә/', 'n. 开...的人, 开局人, 开创人, 开具, 开启工具, 首项 [经] 申请开证人', 'n', NULL, NULL, 'CET4'),
  ('explorer', '/ik''splɒ:rә/', 'n. 探险家, 探测者, 勘探器 [医] 探察器', 'n', 'Christopher Columbus wasn''t an explorer because he loved the sea. He was an explorer because he hated Spanish jails.', '哥伦布不是一位探险家, 因为他热爱大海。他是一位探险家, 因为他讨厌西班牙监狱。', 'CET4'),
  ('offshore', '/ɒ:f''ʃɒ:/', 'a. 海面的, 吹向海面的, 近海的 adv. 向海面', 'adj', NULL, NULL, 'CET4'),
  ('fingernail', '/''fiŋgәneil/', 'n. 手指甲', 'n', 'Ziri uses his fingernail to peel loquats.', '齐里用指甲剥枇杷。', 'CET4'),
  ('scottish', '/''skɒtiʃ/', 'a. 苏格兰的, 苏格兰人的', 'adj', NULL, NULL, 'CET4'),
  ('bowling', '/''bәuliŋ/', 'n. 保龄球戏', 'n', 'At night, we usually go bowling.', '我们经常在夜晚打保龄球。', 'CET4'),
  ('bakery', '/''beikәri/', 'n. 面包店', 'n', 'The girl who works at the bakery is cute.', '在面包房工作的姑娘很可爱。', 'CET4'),
  ('apron', '/''eiprәn/', 'n. 围裙 [医] 围裙', 'n', 'Tom put on an apron.', '汤姆穿上了一条围裙。', 'CET4'),
  ('swap', '/swɒp/', 'n. 以货易货 v. 交换, 替换, 交易 [计] 交换', 'n', NULL, NULL, 'CET4'),
  ('softball', '/''sɒftbɒ:l/', 'n. 垒球运动, 垒球', 'n', NULL, NULL, 'CET4'),
