-- ---------- 5. 补齐补录词的音标与词性（ECDICT 这批词的 pos 列全为 NULL）----------
-- 音标按库内同族词推导，保证与既有音标体系一致（schwa ə、冒号长音、单撇重音）；
-- cd / dr / mm 为缩写，与 B.C. / P.M. 同口径，保留 NULL 不补。

-- website: web /web/ + site /sait/
UPDATE `word_dictionary` SET `phonetic` = '/''websait/' WHERE `word` = 'website';
-- stairs: stair /stєә/ 加复数 -s
UPDATE `word_dictionary` SET `phonetic` = '/stєәz/' WHERE `word` = 'stairs';
-- hotdog: hot /hɒt/ + dog /dɒg/
UPDATE `word_dictionary` SET `phonetic` = '/''hɒtdɒg/' WHERE `word` = 'hotdog';
-- works: work /wә:k/ 加复数 -s
UPDATE `word_dictionary` SET `phonetic` = '/wә:ks/' WHERE `word` = 'works';
-- willingness: willing /'wiliŋ/ 加 -ness
UPDATE `word_dictionary` SET `phonetic` = '/''wiliŋnəs/' WHERE `word` = 'willingness';
-- workplace: work /wә:k/ + place
UPDATE `word_dictionary` SET `phonetic` = '/''wә:kpleis/' WHERE `word` = 'workplace';
-- wounded: wound /wu:nd/ 加 -ed
UPDATE `word_dictionary` SET `phonetic` = '/''wu:ndid/' WHERE `word` = 'wounded';
-- bored: bore /bɒ:/ 加 -d
UPDATE `word_dictionary` SET `phonetic` = '/bɒ:d/' WHERE `word` = 'bored';
-- download: down /daun/ + load /lәud/
UPDATE `word_dictionary` SET `phonetic` = '/daun''lәud/' WHERE `word` = 'download';
-- workforce: work /wә:k/ + force /fɒ:s/
UPDATE `word_dictionary` SET `phonetic` = '/''wә:kfɒ:s/' WHERE `word` = 'workforce';
-- sunglasses: sun /sʌn/ + glass /glɑ:s/ 加 -es
UPDATE `word_dictionary` SET `phonetic` = '/''sʌnglɑ:siz/' WHERE `word` = 'sunglasses';
-- puzzled: puzzle /'pʌzl/ 加 -ed
UPDATE `word_dictionary` SET `phonetic` = '/''pʌzld/' WHERE `word` = 'puzzled';
-- crossroads: cross /krɒs/ + road /rәud/ 加 -s
UPDATE `word_dictionary` SET `phonetic` = '/''krɒsrәudz/' WHERE `word` = 'crossroads';
-- workday: work /wә:k/ + day /dei/
UPDATE `word_dictionary` SET `phonetic` = '/''wә:kdei/' WHERE `word` = 'workday';
-- skillfully: skillful /'skilful/ 加 -ly
UPDATE `word_dictionary` SET `phonetic` = '/''skilfuli/' WHERE `word` = 'skillfully';
-- barbershop: barber /'bɑ:bә/ + shop /ʃɒp/
UPDATE `word_dictionary` SET `phonetic` = '/''bɑ:bәʃɒp/' WHERE `word` = 'barbershop';
-- furnished: furnish /'fә:niʃ/ 加 -ed
UPDATE `word_dictionary` SET `phonetic` = '/''fә:niʃd/' WHERE `word` = 'furnished';
-- walkman: walk + man /mæn/
UPDATE `word_dictionary` SET `phonetic` = '/''wɔ:kmæn/' WHERE `word` = 'walkman';
-- regards: regard /ri'gɑ:d/ 加 -s
UPDATE `word_dictionary` SET `phonetic` = '/ri''gɑ:dz/' WHERE `word` = 'regards';
-- westerner: western /'westәn/ 加 -er
UPDATE `word_dictionary` SET `phonetic` = '/''westәnə/' WHERE `word` = 'westerner';
-- ballpoint: ball /bɒ:l/ + point /pɒint/
UPDATE `word_dictionary` SET `phonetic` = '/''bɒ:lpoint/' WHERE `word` = 'ballpoint';
-- cosy: cozy /'kәuzi/（英式拼写同音）
UPDATE `word_dictionary` SET `phonetic` = '/''kәuzi/' WHERE `word` = 'cosy';
-- workmate: work /wә:k/ + mate /meit/
UPDATE `word_dictionary` SET `phonetic` = '/''wә:kmeit/' WHERE `word` = 'workmate';
-- organiser: organise /'ɒ:gәnaiz/ 加 -er
UPDATE `word_dictionary` SET `phonetic` = '/''ɒ:gәnaizə/' WHERE `word` = 'organiser';

-- a: 冠词
UPDATE `word_dictionary` SET `pos` = 'art' WHERE `word` = 'a';
-- am: be 动词的第一人称单数变位
UPDATE `word_dictionary` SET `pos` = 'aux' WHERE `word` = 'am';
-- tv: 缩写名词
UPDATE `word_dictionary` SET `pos` = 'n' WHERE `word` = 'tv';
-- f: 评分等级，名词用法
UPDATE `word_dictionary` SET `pos` = 'n' WHERE `word` = 'f';
-- grandpa: 与库内 grandfather / grandmother 同口径
UPDATE `word_dictionary` SET `pos` = 'n' WHERE `word` = 'grandpa';
-- download: 与库内 load 同口径，取名词义
UPDATE `word_dictionary` SET `pos` = 'n' WHERE `word` = 'download';
-- founding: found 的动名词
UPDATE `word_dictionary` SET `pos` = 'n' WHERE `word` = 'founding';
-- mm: 毫米，与库内 millimetre 同口径
UPDATE `word_dictionary` SET `pos` = 'n' WHERE `word` = 'mm';
-- skipping: 与库内 skip 同口径
UPDATE `word_dictionary` SET `pos` = 'n' WHERE `word` = 'skipping';
-- organiser: 与库内 organise 同口径
UPDATE `word_dictionary` SET `pos` = 'vt' WHERE `word` = 'organiser';
